quests[74492] = { id = 74492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brandheiße Belastrasza", description = "Rote Welpen können etwas außer Rand und Band geraten, also viel Glück Euch!\n\n: Verbraucht im Laufe der Zeit allen Elan.\n: Stellt sämtlichen Elan her und erhaltet für jeden Elan einen Geschwindigkeitsschub.\n: Verbraucht 'Blutroter Flug' und setzt Abklingzeiten zurück.", sourceObjective = "Helft Belastrasza, durch die Ringe zu gleiten.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[74493] = { id = 74493, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller guten Dinge sind zwei", description = "<Voraxian wirft das seltsame runde Objekt ein paar Mal hoch.>\n\nHmm, es liegt gut in der Hand, als wäre es dafür gemacht. Fragen wir Veritistrasz, ob er mehr darüber weiß.", sourceObjective = "Bestimmt den Ursprung des seltsamen runden Objekts.", progress = "Hoffen wir, dass es dieses Mal etwas Spannendes ist!", completion = "Bei den Titanen... Da bin ich ja über ein Fettfass gestolpert.\n\nEntschuldigt, {name}. Ich werde eine Weile mit Veritistrasz hier sitzen und warten, bis er wieder bereit ist, mit mir zu sprechen.\n\nFalls Ihr noch etwas Interessantes findet, bringt es bitte her.", sourceObjectiveStatus = "unverified-source-field" }
quests[74494] = { id = 74494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schuppe um Schuppe", description = "Das Erwachen des Ältesten war zweifellos eine Bedrohung. Doch es gibt eine weitere Mission, die ich abschließen muss, bevor wir aufbrechen... Andernfalls verlieren wir unsere einzige Chance, es überhaupt zu Ende zu bringen.\n\nWie groß die Unterschiede zwischen dem Zaqalistamm und den Qalashi auch sein mögen, sie sind Drachenschlächter. Ihre Kriegsmaschinen sind für uns nicht weniger tödlich.\n\nIch brauche einen Speer, der jenem Speer ebenbürtig ist, den wir an der Seite des Ältesten sahen. Findet den größten, den Ihr auftreiben könnt, und bringt ihn mir.", sourceObjective = "Bringt Sabellian einen Drachentöterspeer der Zaqali.", progress = "Djaradinwaffen sind abscheuliche Werke und dienen nur einem einzigen Zweck.", completion = "Dies ist der einzige Weg voran.", sourceObjectiveStatus = "unverified-source-field" }
quests[74495] = { id = 74495, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschichte von Hraxian", description = "Hallo, {name}, es ist schön, Euch zu sehen.\n\nWürdet Ihr Euch gerne zu uns ans Feuer gesellen? Ich glaube, es ist an der Zeit, dass wir eine positive Geschichte über den alten Obsidianschwarm zu hören bekommen.\n\nIch habe Euch und Voraxian einst versprochen, dass ich Euch die Geschichte von der Vase erzählen würde, die ich in den Gewölben von Zskera gefunden habe. Ich glaube, jetzt ist der richtige Zeitpunkt dafür.", sourceObjective = "Lauscht der Geschichte von Hraxian.", progress = "Es ist immer ein Vergnügen, {name}.", completion = "<Veritistrasz sitzt für eine Weile stumm da.>\n\nDanke, dass Ihr mir zugehört habt, {name}. Ich habe vieles von meinem Leben vergessen, aber nicht das.\n\nIch hoffe, Hraxians Geschichte kann dem Obsidianschwarm nach allem, was wir hier herausgefunden haben, Hoffnung geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[74501] = { id = 74501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchdringungslager: Glutwind" }
quests[74502] = { id = 74502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gratisgeschenk", sourceObjective = "AUSGABE: Bitte akzeptiert dieses GESCHENK.\n\nGESCHENKVERTEILUNGSPROTOKOLL INITIIERT.", sourceObjectiveStatus = "unverified-source-field" }
quests[74503] = { id = 74503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein weiteres Geschenk", progress = "AUSGABE: Erneuter Zugriff auf Geschenke erfordert autorisierte Marke.", completion = "AUSGABE: Bitte akzeptiert dieses GESCHENK.\n\nGESCHENKVERTEILUNGSPROTOKOLL INITIIERT." }
quests[74510] = { id = 74510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forbidden Reach 2/6" }
quests[74514] = { id = 74514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der langsamste Fanclub", description = "Hat Euch jemals eine Menge zugejubelt? Jedermann ruft Euren Namen, treibt Euch in Richtung Sieg? \n\nDieses Gefühl soll auch Schleimer erleben. Er soll einen Vorgeschmack darauf erhalten, ein Champion zu sein.\n\nNatürlich sprechen wir nicht Schneckisch, also können wir nicht sonderlich viel erreichen. Sammelt ein paar Schnecken, die ihrem Leben einen Sinn verleihen wollen. Schleimer braucht einen Fanclub.", sourceObjective = "Sammelt 8 ziellose Schnecken.", completion = "Perfekt! Verpasst diesen Viechern ein paar \"Größter Schleimer der Stadt\"-Fanartikel, dann sind sie bereit. Unsere Jungs werden motivierter sein als je zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[74515] = { id = 74515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneckenpost", description = "Rennschnecken brauchen vor allem Geschwindigkeit, aber Reitschnecken? Die brauchen auch Ausdauer.\n\nIch schulde einem Kumpel in Loamm ein paar Vorräte. Warum übernehmt Ihr nicht die Lieferung? Das sollte Schleimers Ausdauer verbessern.\n\nOh, und steigt auf keinen Fall ab. Ist kein ordentliches Training, wenn Ihr ständig hoch- und runterspringt.", sourceObjective = "Bringt das Paket zu Terryn in Loamm, ohne von Schleimer abzusteigen. Wenn Ihr zum Absitzen gezwungen werdet, kann Briggul Euch eine neue Lieferung geben.", completion = "Geschwindigkeit und Ausdauer! Diese Schnecke hat beides, Leute. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[74516] = { id = 74516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneckenschnell", description = "Heute machen sie an der örtlichen Rennstrecke Pause, also dachte ich, wir könnten die Gelegenheit nutzen und Schleimers Geschwindigkeit verbessern. Ein bisschen Selbstvertrauen im Heimatrevier sammeln, dachte ich.\n\nMacht zwei Runden auf der Strecke. Mal sehen, wie sich Euer Training auswirkt!", sourceObjective = "Sammelt 1 Rundenmarkierungen, indem Ihr zwei Runden auf der Schneckenstrecke dreht.", completion = "Seht Euch nur an, enger zusammen als Schleimbrüder. Oh, so nenne ich das, wenn zwei Schnecken aneinander kleben bleiben. Passiert schon mal.\n\nIhr macht beide gute Fortschritte. Ich bin gespannt, wo es mit Euch hingeht!", sourceObjectiveStatus = "unverified-source-field" }
quests[74517] = { id = 74517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geländeschnecke", description = "Das Leben in diesen Höhlen ist ja aufregend, aber Schleimer hat in der Welt über der Erde eine Zukunft. Und zwar als Euer treues Reittier.\n\nUnd das bedeutet, wir müssen ihn auf alle möglichen Umgebungen vorbereiten.\n\nZum Glück gibt es auf den Dracheninseln alle möglichen Gebiete. Warum dreht Ihr nicht eine Runde mit ihm? Gebt ihm einen Vorgeschmack auf die Zukunft. Eine Runde pro Ort sollte reichen.", sourceObjective = "Reitet Schleimer durch Schneckenmarkierungen im Rastlosen Sumpfland, der Steppe des Wanderers, den Oberen Frostlanden und den Wandernden Sanden.", completion = "Hier kommt Schleimer, außergewöhnlicher Reisender! Der Schleim sieht gut aus, die Membranen sind schön durchsichtig, keine Risse im Haus.\n\nDanke, dass Ihr Euch um ihn kümmert.", sourceObjectiveStatus = "unverified-source-field" }
quests[74518] = { id = 74518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widerstandstraining", description = "Diese Höhlen machen es meinen armen Schnecken nicht leicht, darum füttere ich sie mit besonderen Kristallen. Die halten ihre Häuser hart und glänzend. \n\nSchleimer futtert aber mehr als seinen Anteil, also sitze ich auf dem Trockenen. \n\nKönntet Ihr in der Zaralekhöhle ein paar Kristalle sammeln? Wir brauchen ein paar verschiedene, damit wir Schleimer auf alle möglichen Umgebungen vorbereiten können.", sourceObjective = "Sammelt 5 leuchtende Kristalle, 5 Schwefelkristalle und 5 Magmakristalle in der Zaralekhöhle.", progress = "Alle sagen, dass ihre Schnecken feste, gesunde Häuser haben sollen, aber wenn sie dann die Kristalle sammeln sollen? Sind sie zu beschäftigt oder haben Angst.\n\nVercrokte Feiglinge...", completion = "So muss es sein! Ihr werdet sehen, Schleimers Haus kriegt schicken Schein. Puh, fast schon ein Zungenbrecher, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[74519] = { id = 74519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebt Glibber", description = "Jeder Schneckenausbilder weiß genau, dass es um den Glibber geht. Den Schleim. Das Glitschige. So macht man aus einer schnellen Schnecke einen Champion.\n\nSchleimer könnte mal wieder eingerieben werden. Geht raus da und sammelt etwas Glibber von den Schleimspuren in der Umgebung, um ihn glitschiger zu machen. Ha.", sourceObjective = "Sammelt Glibber von Schleimen in der Zaralekhöhle.", completion = "Na, das ist mal ein schleimiger Schleimer. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[74520] = { id = 74520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weniger Ladung", description = "Diese Djaradin glauben wohl, dass ihnen diese Höhlen gehören, wenn sie herkommen und unsere Vorräte plündern. Wie soll ich unter diesen Bedingungen Champions trainieren?\n\nKönnt Ihr mir einen Gefallen tun und diese Vorräte zurückholen? Ohne sie kann ich Schleimer nicht trainieren. \n\nAußerdem könnte der große Kerl einen Ruhetag brauchen.", sourceObjective = "Sammelt 10 gestohlene Vorräte von Djaradin in Igiras Wacht.", progress = "Hauspolitur, Schleimpaste, Rennsteine... Crok das, wir brauchen die Vorräte zurück!", completion = "Großartig! Ihr habt Euch wirklich gut geschlagen. Jetzt können wir mit Schleimers Training fortfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[74521] = { id = 74521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Flamme, erloschen", description = "Sarkareth gibt es nicht mehr.\n\nSeine Hybris machte ihn anfällig für die dunklen Einflüsse, die unseren Schwarm schon seit Jahrtausenden angreifen. Genau wie Neltharion vor ihm.\n\nIch glaube, Glutthal will mehr Informationen, als Furorion und Sabellian ihr geben können. Sie braucht vielleicht Hilfe.", sourceObjective = "Sprecht mit Furorion oder Sabellian.", completion = "Da sind wir, {name}.\n\nIch gebe zu, dass das Vermächtnis des schwarzen Drachenschwarms geprägt ist von vielen fragwürdigen, boshaften oder ganz und gar abscheulichen Taten.\n\nWerdet Euch also dem Gewicht meiner Worte gewahr, wenn ich sage, dass das, was sich vor uns befindet, vielleicht den schlimmsten Teil dieses Vermächtnisses darstellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[74522] = { id = 74522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überreste", description = "Wisst Ihr, manche betrachten mich als Wunder. Allerdings war meine Geburt alles andere als natürlich. Ich wurde erschaffen, ganz ähnlich wie diese Kreaturen hier geschaffen wurden. Viele starben eines qualvollen, tragischen Todes, damit ich leben konnte.\n\nDiese... Gleichgültigkeit dem Leben gegenüber ist etwas, das ich ablegen möchte.\n\nNehmt dies und vernichtet damit die intakten Probenbehälter auf unserem Weg. Nichts verdient es, so zu leiden.", sourceObjective = "Zerstört 7 Probenbehälter mit Schwarzkrallennapalm.", progress = "Wir müssen diese Sache jetzt und hier beenden.", completion = "Endlich hat das Leiden dieser Abscheulichkeiten ein Ende gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[74523] = { id = 74523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schuld eines Verräters", description = "Diese Schmeichler bringen Schande über sich selbst und über den schwarzen Drachenschwarm. Sie sind ganz klar bereit, im Dienste der dunklen Machenschaften meines Vaters ihr Leben zu geben.\n\nWir sollten ihnen ihren Wunsch erfüllen.", sourceObjective = "Bezwingt die Neltharionloyalisten.", completion = "Furorions Schwarzkrallen sind vielleicht keine Frontsoldaten, aber sie sollten den Rest erledigen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[74525] = { id = 74525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eidgebunden", description = "<Der Körper des Djaradin ist dürr und ausgezehrt, er wurde von den hungrigen Maschinen in diesem finsteren Labor seiner Lebenskraft beraubt.\n\nVielleicht sind hier noch weitere Djaradin eingesperrt, denen dieser Horror erspart werden kann.>", sourceObjective = "Befreit die eingesperrten Djaradin.", progress = "Der schwarze Drachenschwarm wird durch unsere Handlungen definiert, nicht durch unsere Errungenschaften.", completion = "Mögen sie im Tod die Ehre finden, die ihnen im Leben verwehrt wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[74538] = { id = 74538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bomben auf Ballisten", description = "Versteht mich nicht falsch, die Djaradin sind erfahrene Drachentöter. Aber in diesem Moment stehen ihre skrupellosesten Vorgehensweisen ganz im Schatten der verheerenden Kraft ihrer Schlachtfeldballisten, denn diese können jede Bedrohung aus großer Entfernung ausschalten.\n\nIch habe so viele gute Soldaten durch diese mächtigen Waffen verloren.\n\nEs ist extrem wichtig, dass wir die Ballisten zerstören, um somit auf dem Schlachtfeld für Chancengleichheit zu sorgen und in die Lüfte steigen zu können. Dann ist es sogar möglich, dass wir in diesem Krieg die Oberhand gewinnen.", sourceObjective = "Zerstört die schweren Djaradinwaffen in den Schlachtfeldruinen.", completion = "Selbst von hier oben sieht man den Rauch! Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[74539] = { id = 74539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausdünnen ihrer Verteidigung", description = "Die Feuerrufer sind äußerst formidable Gegner. Dank ihrer mächtigen tödlichen Magie können sie alles pulverisieren, was ihnen zu nahe kommt.\n\nSie haben sich auf hohen Felsvorsprüngen strategisch gut positioniert, und das macht es schwierig, sie zu erreichen. Wir können allerdings nicht länger zulassen, dass sie von dort aus unsere Streitkräfte dezimieren.\n\nDas Schicksal unserer Streitkräfte wird durch Euer Handeln mitbestimmt. Viel Glück!", sourceObjective = "Neutralisiert die Flammenzungen der Zaqali in den Schlachtfeldruinen.", completion = "Und wieder haben wir unserem Feind einen Vorteil genommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[74540] = { id = 74540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abfangen der Kommunikation", description = "{name}, wir brauchen Infos, und zwar sofort.\n\nIrgendwo in einem der Lager der Djaradin hält sich ihr Feldgeneral auf. Er ist ein erfahrener und außerordentlich starker Gegner und ist für viele Angriffe auf unsere Streitkräfte verantwortlich.\n\nUnseren örtlichen Agenten zufolge könnte er im Besitz wichtiger Militärbefehle sein, in denen ihre nächste Offensive und die Orte ihrer neuen Versorgungslinien aufgeführt sind.\n\nEs ist äußerst wichtig, dass wir uns diese Befehle schnappen. Wir müssen verhindern, dass die Djaradin die Oberhand gewinnen.", sourceObjective = "Besiegt Kriegsruferin Ronvath und beschafft Euch die Invasionspläne in den Schlachtfeldruinen.", progress = "Lagebericht!", completion = "Das hatte ich keinesfalls erwartet, Soldat.\n\nLaut diesem Bericht haben die Djaradin eine neue drachenähnliche Art in den Höhlen östlich von hier entdeckt.\n\n<Ignax zeigt mit dem Finger auf einen Punkt auf der Karte.>\n\nSie haben den Ort auch als eines ihrer Angriffsziele markiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[74542] = { id = 74542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftüberlegenheit", description = "<Ignax blickt auf und Ihr erkennt ein kleines Lächeln in seinem Gesicht.>\n\nNur wenige meiner Soldaten haben Erfahrung, wie man mit Drachen an seiner Seite kämpft. Was für ein glorreicher Tag.\n\nIhre Anwesenheit verschafft uns Zuversicht, {class}. Wir müssen dem Vorstoß der Djaradin jetzt ein für alle Mal ein Ende setzen.", sourceObjective = "Besiegt die Streitkräfte der Djaradin und unterbindet ihren Vorstoß in den Schlachtfeldruinen.", completion = "Das muss das Brutgebiet sein, das im gestohlenen Bericht erwähnt wurde.\n\nAber warum sind die Djaradin hier tot?\n\nKommen wir zu spät?", sourceObjectiveStatus = "unverified-source-field" }
quests[74557] = { id = 74557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung des Unbekannten", description = "Wir können nur mutmaßen, dass die marschierenden Djaradin von irgendetwas angegriffen wurden. Wer könnte dahinter stecken?\n\nWir sollten uns die Sache näher anschauen, bevor wir fortfahren.", sourceObjective = "Untersucht den Ursprung und die Motivationen der Kreaturen in diesem Gebiet.", completion = "Die Djaradin wurden also hier von einer unbekannten Streitmacht der Drachkin aufgehalten. Angesichts der zahlreichen Toten scheinen diese Drachkin ebenso brutal wie die Djaradin zu sein.\n\nAm meisten Sorgen macht mir, dass sie weiterhin Neltharions Banner tragen. Das bedeutet, dass sie ihm und der Aufgabe, die er ihnen einst übertrug, weiter treu ergeben sind.\n\nWir müssen auf der Hut sein, die Sache wurde gerade noch komplizierter.", sourceObjectiveStatus = "unverified-source-field" }
quests[74562] = { id = 74562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiungsaktion", description = "Käfige, Ketten und Transportwagen... Ich glaube, wir können uns alle denken, wohin das führt.\n\nWenn die Drakoniden planen, die Kriecherdrachen gefangenzunehmen und zu versklaven, sind sie keinen Deut besser als die Djaradin. \n\nSchaut, was Ihr tun könnt, um Ihre Pläne zu durchkreuzen.", sourceObjective = "Haltet die Wilderer auf und verhindert, dass sie die Kriecherdrachen gefangen nehmen.", completion = "Die Kriecherdrachen sind frei! Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[74563] = { id = 74563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlimmer geht's nicht", description = "Alles hier deutet auf ein wohlkoordiniertes Unterfangen hin. Die Kriecherdrachen sind fast wie wilde Tiere. Ohne unsere Hilfe haben sie keine Chance.\n\nFindet den Anführer ihrer Operation und setzt dem Ganzen ein Ende.", sourceObjective = "Findet die Drakonide, die die Wilderer anführt, und eliminiert sie.", completion = "Die Kriecherdrachen wurden also nicht hier, sondern in Aberrus geboren? Waren sie womöglich Teil seiner Experimente, die letztendlich zur Erschaffung der Dracthyr führten? Der Gedanke, wie leicht es für Neltharion war, Leben zu erschaffen wie zu vernichten, lässt mich erschaudern. Dennoch war dies ein schwerer Schlag für ihr Unterfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[74568] = { id = 74568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jene, die uns verbrennen wollen", description = "Die Djaradin und ihre Primalistenverbündeten sind eine wahre Landplage, {name}.\n\nLöscht sie aus.", sourceObjective = "Tötet Djaradin und Primalisten, die die Ebenen von Ohn'ahra angreifen.", progress = "Wie läuft die Schlacht?", completion = "Gut. Nichts stoppt ein Ritual so gut wie ein toter Ritualist.", sourceObjectiveStatus = "unverified-source-field" }
quests[74569] = { id = 74569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verweigert ihnen die Ressourcen", description = "Diese gesamte Invasion wurde mit dem einzigen Ziel durchgeführt, Rohmaterial in nie dagewesener Menge mit elementarer Macht zu erfüllen.\n\nWir kennen vielleicht Fyrakks schlussendliches Ziel nicht, aber es scheint eine gute Idee zu sein, seine Bemühungen zu behindern.\n\nWenn er diese Materialien will, werden wir sie ihm vorenthalten.", sourceObjective = "Holt Infusionsvorräte von Fyrakks Streitkräften zurück.", progress = "Lasst ihm nichts.", completion = "Ausgezeichnet. Alles, was wir ihnen abnehmen können, erkauft uns Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[74570] = { id = 74570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für unsere Verwundeten", description = "{name}, unsere Streitkräfte waren auf so einen Ansturm nicht vorbereitet.\n\nDiese Djaradin kämpfen erbitterter als die Gegner, mit denen wir es in der Vergangenheit zu tun hatten. Wir haben Verwundete hinter den feindlichen Reihen.\n\nWenn Ihr Kenntnisse in der Heilkunst habt, bitte ich Euch, diese einzusetzen. Wenn nicht, haben wir Bandagen, mit denen Ihr den Verwundeten helfen könnt.\n\nBitte helft uns, unsere Leute in Sicherheit zu bringen.", sourceObjective = "Heilt 6 verwundete Wächter mit den zur Verfügung gestellten Bandagen oder Euren eigenen Fähigkeiten.", completion = "Viele sind gegen diese Eindringlinge gefallen, die unsere heiligen Ebenen entweihen. Ich danke Euch, dass Ihr diese Welle des Todes heute eingedämmt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[74571] = { id = 74571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht einen Weg frei", description = "Die Djaradin befestigen ihren Brückenkopf. Wir können es ihnen nicht erlauben, dass sie sich weiter eingraben, sonst werden ihre Vorstöße zu Eroberungen.\n\nZerstört ihre Barrikaden, bevor das geschehen kann.", sourceObjective = "Zerstört Barrikaden der Djaradin.", progress = "Lasst ihnen nichts, hinter dem sie sich verstecken können.", completion = "Ihre Verteidigung ist durchbrochen. Jetzt wird es einfacher, ihre Vorstöße zurückzuwerfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[74572] = { id = 74572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst es regnen", description = "Die Djaradin stecken die Ebenen mit ihrem rücksichtslosen Einsatz von Feuermagie in Brand. Wir müssen schnell handeln, bevor diese kleinen Funken zu einem tobenden Lauffeuer werden.\n\nNicht weit von hier befindet sich ein tiefer Teich mit frischem Wasser. Gleitet auf Eurem Drachen dicht über der Oberfläche dahin, sammelt, so viel Ihr tragen könnt, und fliegt dann über das Lager der Djaradin, um die Feuer unter Euch zu löschen.\n\nDas wird nicht ausreichen, um die größeren Feuer zu löschen, aber es wird uns Zeit erkaufen.", sourceObjective = "Löscht Feuer im Lager der Djaradin.", progress = "Schnell, bevor die Flammen sich ausbreiten!", completion = "Ich habe die Dampfwolken von hier gesehen. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[74573] = { id = 74573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftunterstützung", description = "Die Portale der Primalisten müssen zerstört werden, wenn wir sie davon abhalten wollen, dieses Rohmaterial mit elementarer Energie zu erfüllen.\n\nLeider sind ihre Stützpunkte zu stark geschützt, als dass ein einziger Angriff bleibenden Schaden anrichten könnte, ob er nun von Sterblichen oder Drachen ausgeführt wird.\n\nGemeinsam gibt es jedoch eine Möglichkeit.\n\nNehmt diesen Samen. Schwächt damit ihre Verteidigung, dann werden wir zuschlagen können, bevor sie reagieren können.", sourceObjective = "Schwächt die Verteidigung der Portale.", completion = "Gute Arbeit. Das sollte ihnen den Zeitplan verhageln.", sourceObjectiveStatus = "unverified-source-field" }
quests[74576] = { id = 74576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restauriertes Schmuckstück der Hakkari", description = "<Die Fragmente des Schmuckstücks fügen sich mühelos zusammen, nach einem geringfügigen Eingriff ziehen sie sich gegenseitig an.\n\nEin leises Brummen von den Überresten einer uralten Macht ist zu hören. Zu viel, um ohne Bedeutung zu sein, aber zu wenig, um von großem Nutzen sein zu können.\n\nIrgendwo hat irgendwer sicher Interesse an Eurer Entdeckung.>", sourceObjective = "Findet jemanden, der Interesse am restaurierten Schmuckstück der Hakkari hat.", completion = "Ein altes Schmuckstück der Hakkari, was? Ich werde es nicht wagen, zu fragen, WIE es in Euren Besitz gelangt ist, aber es gibt keinen Zweifel über seine Herkunft.\n\nSolltet Ihr Euch nochmal innerhalb der Mauern Zul'Gurubs befinden, so haltet die Augen nach weiteren Schätzen offen... und bringt sie mir.\n\nWir werden uns bald wiedersehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[74581] = { id = 74581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die langen Messer", sourceObjective = "Sprecht mit Kaltunk im Tal der Prüfungen.", completion = "Seid Ihr das, {name}? Seht Euch an, wie Ihr gewachsen seid! Aber warum seid Ihr hier?\n\nHaben sie Euch geschickt, um Gor'krosh zu erledigen? Den Ahnen sei Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[74695] = { id = 74695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Münzen der Razzashi, Hakkari und zulianische Münzen", progress = "Ich suche die Symbole der Macht, die als Münzen der Stämme bekannt sind. Diese Währung wurde von den verschiedenen Bewohnern Zul'Gurubs verwendet, und jede ist mit einem subtilen, aber mächtigen Mojo versehen.\n\nEs gibt neun verschiedene Arten. Wenn Ihr doppelte Exemplare habe, tausche ich drei davon gegen eine Wertmarke ein.\n\nUnd ja, die werdet Ihr mir schon bald wiederbringen.", completion = "Ausgezeichnet! Dieser Münzsatz wird meine wachsende Sammlung hervorragend ergänzen.\n\nHier ist Eure Marke, wie versprochen." }
quests[74696] = { id = 74696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Münzen der Gurubashi, Blutfratzen und Bleichborken", progress = "Ich suche die Symbole der Macht, die als Münzen der Stämme bekannt sind. Diese Währung wurde von den verschiedenen Bewohnern Zul'Gurubs verwendet, und jede ist mit einem subtilen, aber mächtigen Mojo versehen.\n\nEs gibt neun verschiedene Arten. Wenn Ihr doppelte Exemplare habe, tausche ich drei davon gegen eine Wertmarke ein.\n\nUnd ja, die werdet Ihr mir schon bald wiederbringen.", completion = "Ausgezeichnet! Dieser Münzsatz wird meine wachsende Sammlung hervorragend ergänzen.\n\nHier ist Eure Marke, wie versprochen." }
quests[74697] = { id = 74697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Münzen der Sandwüter, Schädelspalter und Blutskalpe", progress = "Ich suche die Symbole der Macht, die als Münzen der Stämme bekannt sind. Diese Währung wurde von den verschiedenen Bewohnern Zul'Gurubs verwendet, und jede ist mit einem subtilen, aber mächtigen Mojo versehen.\n\nEs gibt neun verschiedene Arten. Wenn Ihr doppelte Exemplare habe, tausche ich drei davon gegen eine Wertmarke ein.\n\nUnd ja, die werdet Ihr mir schon bald wiederbringen.", completion = "Ausgezeichnet! Dieser Münzsatz wird meine wachsende Sammlung hervorragend ergänzen.\n\nHier ist Eure Marke, wie versprochen." }
quests[74769] = { id = 74769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegen die Eisenflut stemmen", description = "Leider sind wir nicht die Einzigen, die auf die Chancen aufmerksam geworden sind, die die Insel bietet.\n\nUnsere Späher haben uns von Piratenschiffen berichtet, die vor der Küste vor Anker liegen. Die ersten Langboote sind an den nordöstlichen Stränden angelandet.\n\nUnsere Geschichte ist nicht dafür da, von ihnen geplündert zu werden. Wenn Ihr diesen Piraten begegnet, lasst sie zurück zu ihren kleinen Booten schwimmen.", sourceObjective = "Tötet 10 Piraten der Eisenfluträuber an der Sturmküste.", completion = "Ich danke Euch. Mit etwas Glück haben diese Briganten etwas gelernt.\n\nWir sind willens, diese Lande und ihre Geheimnisse zu verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[74771] = { id = 74771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüsseljagd", description = "Meine Taschen sind leer. Ich habe keine Gewölbeschlüssel mehr!\n\nVersucht doch, weitere Schlüssel von Zskera zu finden, dann sehen Jeb und ich, was wir damit aufdecken! Wenn wir unsere Schlüssel zusammenlegen, können wir eine Menge Türen öffnen!", sourceObjective = "Findet 3 Gewölbeschlüssel von Zskera auf der Verbotenen Insel und bringt sie zu Pfadfinderin Tacha.", progress = "Habt Ihr Schlüssel gefunden?", completion = "Wir haben auch noch mehr Schlüssel gefunden! Ich kann's kaum erwarten, mehr Türen zu öffnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[74774] = { id = 74774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Schlüssel", description = "Ich habe weitere Schlüssel! Ihr könnt sie nutzen, um mehr verschlossene Türen zu öffnen!\n\nBitte, nehmt sie und nutzt sie in der Kammer.", sourceObjective = "Nehmt die Schlüssel.", sourceObjectiveStatus = "unverified-source-field" }
quests[74775] = { id = 74775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anhänger von Fyrakk: Kretchenzorn", description = "<Fyrakks Anhänger ist gefallen. Vielleicht spenden die Überreste dieser Bestie denen etwas Trost, deren Lande verwüstet wurden.>", sourceObjective = "Sammelt den Kopf von Kretchenzorn ein.", progress = "Wie ich höre, habt Ihr Euch einem Anhänger von Fyrakk gestellt.", completion = "Dann ist das also die Bestie, die einer solchen Inkarnation die Treue schwört. Ihr Fanatismus schwelte seit ganzen Zeitaltern dieser Welt.\n\nIch kann solch einen tiefgehenden Hass nicht begreifen.\n\nIch danke Euch, dass Ihr diese Flamme des Zorns auf unseren Ebenen gelöscht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[74783] = { id = 74783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Klang der Stille", description = "Es ist viele Jahre her, dass Shandaral wahre Stille kannte. Wenn wir Glück haben, werden unsere heutigen Taten den Echos dieses verfluchten Orts erlauben, endlich zu verstummen.\n\nWir werdet zweifellos auf den Inseln gebraucht... und es ist höchste Zeit, dass ich ebenfalls dort hinfliege.", sourceObjective = "Kehrt zu Kalecgos im Azurblauen Gebirge zurück.", completion = "Die Nachwirkungen des Konflikts in Shandaral lagen so viele Jahre wie ein Sargtuch über unserem Schwarm. Dass Lanigosa all diese Zeit daran gearbeitet hat, diese Geister zur Ruhe zu betten...\n\nIch danke Euch, dass Ihr ihr geholfen habt, {name}. Ihr habt Euch erneut als ein wahrer Verbündeter meines Volkes erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[74784] = { id = 74784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbotene Insel 1/3 (FI)" }
quests[74786] = { id = 74786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneck, was in dir steckt: Schimmerschnecke", description = "Ich rieche eine Schnecke bei Euch, doch irgendetwas ist komisch. Haltet Ihr mich hin?\n\nViele wissen das nicht, doch Schnecken sind besonders anfällig für Gruppenzwang. Zeigt mir die Wunderschnecke, die Ihr da habt. Vielleicht können wir Schleimer dadurch etwas inspirieren.", sourceObjective = "Beschwört eine Schimmerschnecke der maximalen Kamphaustierstufe und zeigt sie Briggul.", completion = "Na, diese Schimmerschale macht ihrem Namen wirklich alle Ehre! Die glänzt fast heller als die Kristalle der Höhle.\n\nWirklich beeindruckende Schneckenarbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[74787] = { id = 74787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und das Haus ist auch dabei", description = "Hmm. Habt Ihr je eine Schnecke geritten?\n\nIch habe Generationen von Rennschneckenchampions trainiert, aber jetzt ist mir der schwerste Fall aller Zeiten begegnet. Das Problem ist, er ist zu vercrokt groß. Darf direkt mal nicht antreten.\n\nAber es wäre eine Schande, so ein tolles Exemplar in einem Eimer zu lassen. Wenn Ihr mir dabei helft, Schleimer zu dem Rennchampion zu machen, der in ihm steckt, überlasse ich ihn Euch!", sourceObjective = "Stellt Euch Schleimer vor.", completion = "Er mag Euch! Na ja, zumindest hasst er Euch nicht. Ist bei Schnecken nicht so leicht zu sagen.\n\nJetzt müsst Ihr nur jeden Tag herkommen, um Schleimers Training durchzuführen. Jetzt ist er zwar langsam, aber wir machen ihm schon Feuer unterm Haus.", sourceObjectiveStatus = "unverified-source-field" }
quests[74792] = { id = 74792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da sind überall Sterne!", sourceObjective = "Besiegt Sternguckerin Zenoth in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[74794] = { id = 74794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweimal am Tag richtig", sourceObjective = "Besiegt die fehlerhafte Matrix in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[74795] = { id = 74795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltsames rundes Objekt", description = "<Dieses Objekt sah in den Gewölben von Zskera fehl am Platze aus. Es ist rund, mit drei Einkerbungen in Form von Krallen. Vielleicht würde Voraxian sich dafür interessieren.>", sourceObjective = "Bringt das seltsame runde Objekt zu Voraxian am Rusza'thar-Vorstoß.\n\nBereitgestellter Gegenstand:", completion = "Hmm, rund... deutliche Klauenlöcher... leicht nachgiebig... Ich habe keine Ahnung, was das ist. Vielleicht eine Art Wurfwaffe?\n\nWie aufregend!", sourceObjectiveStatus = "unverified-source-field" }
quests[74796] = { id = 74796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine verstaubte Vase", description = "<Ihr habt eine Vase gefunden. Sie scheint einen schwarzen Drachen darzustellen, der gegen etwas kämpft, das ein Djaradin sein könnte. Voraxian könnte daran interessiert sein.>", sourceObjective = "Bringt die staubige Vase zu Voraxian am Rusza'thar-Vorstoß.\n\nBereitgestellter Gegenstand:", completion = "<Voraxian sieht sich die Vase genau an und studiert die Schnitzereien.>\n\nHmm, ja, ich glaube, Ihr habt recht, {name}. Das sieht aus wie ein Djaradin.\n\nAber es ist eine Vase, vermutlich nicht sehr spannend. Erwartet nicht zu viel.", sourceObjectiveStatus = "unverified-source-field" }
quests[74835] = { id = 74835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enok der Stinkende", sourceObjective = "Besiegt Enok den Stinkenden in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[74836] = { id = 74836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Berufung", sourceObjective = "Besiegt Izal Weißmond in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[74837] = { id = 74837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfoten des Donners", sourceObjective = "Besiegt Vikshi Donnerpfote in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[74838] = { id = 74838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lyver", sourceObjective = "Besiegt Lyver in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[74839] = { id = 74839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallkreisel", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[74840] = { id = 74840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharf wie Feuerstein", sourceObjective = "Besiegt Morgrum Glutstein in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[74841] = { id = 74841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adinakon", sourceObjective = "Besiegt Adinakon in einem Haustierkampf.", sourceObjectiveStatus = "unverified-source-field" }
quests[74842] = { id = 74842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallkreisel - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[74847] = { id = 74847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glutthal wartet", description = "Wir können uns noch lange nicht entspannen, aber wenigstens haben wir ein stabiles Lager... für den Moment. Ich sollte die Operation von hier an alleine im Griff haben.\n\nGlutthal ist angekommen, als Ihr unterwegs gewesen seid. Sie und ihre Verbündeten überwachen die Gegend von den Klippen aus. Vielleicht solltet Ihr Euch bei ihr melden. Sie sollte nicht versuchen, die Insel alleine einzunehmen.", sourceObjective = "Trefft Euch mit Glutthal oben auf den Klippen des Morqutdorfs.", completion = "Das war unser Ausbildungsgelände... und für viele wurde es ihr letzter Ruheort.\n\nSo viele Geheimnisse sind hier begraben. So viele Fragen. Mit etwas Glück finden wir vielleicht die Antworten.", sourceObjectiveStatus = "unverified-source-field" }
quests[74857] = { id = 74857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mausdetektiv", description = "Normalerweise vertreibe ich Fremde von meinem Grundstück, aber heute mache ich eine Ausnahme.\n\nMeine Schnüffelmaus ist verschwunden. Es sieht Persii nicht ähnlich, mich zu ignorieren, wenn ich sie rufe...\n\nIch kann nicht so gut riechen wie andere Niffen. Ohne Persiis Hilfe kann ich mich nicht um die Ernte kümmern.\n\nSie muss solche Angst haben, so ganz allein da draußen... Bitte, Ihr müsst Persii finden!", sourceObjective = "Sucht nach der vermissten Maus.", completion = "Dieser Niffen braucht also seine Maus, was? Hmm...", sourceObjectiveStatus = "unverified-source-field" }
quests[74858] = { id = 74858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agrulkultur", description = "Die Niffen sagen, dass Schnüffelmäuse einen sehr guten Geruchssinn haben. Sie finden ihren Weg durch die Höhle und spüren die schnellsten Rennschnecken auf. Sie können sogar Leuchtsporen erschnüffeln, die erntereif sind.\n\nAber ich habe auch eine gute Nase. Vielleicht kann ich ja sogar diese Leuchtsporen erschnüffeln!\n\nLasst uns die Ernte für den Einsiedler einbringen. So können wir ihm zeigen, dass es nicht so schlimm ist, dass seine Mäusefreundin nicht hier ist... weil ich einspringen kann!", sourceObjective = "Sammelt 6 Leuchtsporen.", progress = "Schnüffelmäuse würden das sicher viel einfacher machen. Aber harte Arbeit macht mir nichts aus!", completion = "Seht Ihr? So gut wie eine Schnüffelmaus!\n\nIch hoffe, der Einsiedler sieht das auch so...", sourceObjectiveStatus = "unverified-source-field" }
quests[74859] = { id = 74859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporenmottenjäger", description = "Sieht aus, als würden Sporenmotten die Ernte hier vernichten.\n\nWenn sie weiter alle Sporen fressen, wird es für den Einsiedler nichts mehr zu ernten geben.\n\nWir müssen die Sporenmotten erledigen. Damit sichern wir die Ernte, und ich kann zeigen, dass ich mich um einen Hof kümmern kann.", sourceObjective = "Tötet 10 Sporenmotten.", progress = "Wenn wir die Schädlinge nicht unter Kontrolle bekommen, wachsen die Sporen nicht.", completion = "Damit sollten die Sporen für eine Weile sicher sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[74860] = { id = 74860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine nette Vorstellung", description = "Es ist an der Zeit, die Ernte zum Einsiedler zu bringen. Wenn er sieht, was wir für gute Arbeit geleistet haben, wird er mich vielleicht als Landarbeiter einstellen!\n\nIch... wollte ihn schon mal ansprechen und fragen, ob er einen Helfer braucht.\n\nAber er scheint Gäste nicht zu mögen. Besonders Drogbar. Also bin ich nervös geworden und weggerannt.\n\nIhr habt nach seiner Maus gesucht. Könntet Ihr mich vielleicht vorstellen?", sourceObjective = "Liefert die Ernte ab und stellt YarrenAgrul vor.", progress = "Ihr müsst Persii finden, bevor es zu spät ist!", completion = "Der Drogbar ist davongerannt, weil er schuldig ist. Kein Zweifel!", sourceObjectiveStatus = "unverified-source-field" }
quests[74861] = { id = 74861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unfreundliche Konfrontation", sourceObjective = "Findet Agrul.", completion = "Ich hätte niemals für Malrogg arbeiten sollen...", sourceObjectiveStatus = "unverified-source-field" }
quests[74866] = { id = 74866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tagebucheintrag: Experimente", description = "<Diese uralte Seite ist in umgebender Magie gebunden und in einem alten drakonischen Dialekt verfasst.>\n\n<Schuppenkommandanten könnten großes Interesse an dem Inhalt dieses Dokuments haben.>", sourceObjective = "Sammelt einen Tagebucheintrag.", progress = "Konntet Ihr irgendetwas von Interesse finden, {name}?", completion = "Gut. Weiteres zu unserer Geschichte in den Worten jemandes, der sie gelebt hat.\n\n<Azurathel liest sich den Tagebucheintrag durch und wird dabei immer stoischer.>\n\nDas ist... verstörend. Als Soldaten wussten wir, dass wir zu einem gewissen Grad entbehrlich waren. Aber das so zu lesen...\n\nDanke, dass Ihr mir das gebracht habt. Wir müssen das übersetzen lassen, damit andere es lesen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[74869] = { id = 74869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urzeitliche Antworten", description = "Enthüllungen erwarten uns in diesem Gewölbe. Vielleicht finden wir einen Weg, uns vor der Magie der Primalisten zu schützen. Die Elementare, die sich in diesen Gewölben verstecken, sind wild, uralt und unterstehen nicht der Kontrolle der Primalisten. Vielleicht bergen sie das Geheimnis, wie wir den Elementaren an der Oberfläche helfen können.\n\nIch habe eine Idee. Wir brauchen vier urzeitliche Kerne. Dann können wir einen Talisman herstellen, der die Elementare draußen läutern und aus der Knechtschaft der Primalisten befreien kann.\n\nWenn Ihr uns helft, teile ich mit Euch, was wir hier gefunden haben.", sourceObjective = "Sammelt je einen urzeitlichen Erd-, Feuer-, Wasser- und Sturmkern von den Elementaren in den Gewölben von Zskera.", progress = "Habt Ihr die Kerne gefunden?", completion = "Diese urzeitlichen Kerne sind alles, was ich brauche.\n\nLasst mich die Dinge, die ich hier herausgefunden habe, mit Euch teilen. Sie könnten Euch von Nutzen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[74871] = { id = 74871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funken des Lebens: Die Verbotene Insel", description = "Die Verbotene Insel ist von der Vielfalt der Dracheninseln umgeben.\n\nGeht und erkundet und fangt Funken ein, aber hütet Euch vor Herausforderern, die Euch über den Weg laufen könnten.", sourceObjective = "Sammelt 50 Funken des Lebens auf der Verbotenen Insel, während Ihr im Kriegsmodus seid.", progress = "Einfach durch die Tür. Ihr könnt es nicht verfehlen.", completion = "Das Abkommen dankt Euch, zweifellos.", sourceObjectiveStatus = "unverified-source-field" }
quests[74875] = { id = 74875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühlingsernter", description = "Falls Ihr nach Arbeit sucht - ich habe gehört, dass es in den Siedlungen in der Nähe großer Städte - in Klingenhügel, in Brill, im Dorf der Bluthufe und am Falkenplatz - Magier geben soll, die Eiersucher anstellen, die ihnen bei ihren Forschungen helfen. Ich kenne keine Einzelheiten, aber die werden sie Euch sicher gerne geben.", sourceObjective = "Sprecht mit einem Frühlingsernter in Klingenhügel, in Brill, im Dorf der Bluthufe oder auf dem Falkenplatz.", completion = "Ja! Ja, ich glaube, ich habe genau die richtige Aufgabe für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[74876] = { id = 74876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Freundschaftssystem", description = "Oh, hallo. Habe ich wieder laut gedacht?\n\nIch wollte andere nicht mit meinen Problemen belasten, aber...\n\nIch bin ein Schnüffelsucher, müsst Ihr wissen! Wir finden überall in der Höhle einzigartige und wunderbare Orte. Aber wir haben hier in Loamm eine wichtige Regel: Wir befolgen stets das Freundschaftssystem. Niemand gräbt alleine!\n\nIch arbeite mit der gleichen Freundin zusammen, seit wir klein waren, aber sie ist jetzt so beschäftigt, dass sie nicht mehr graben kann. Ich habe einen interessanten neuen Geruch gefunden. Bisher hatte ich eine Freundin...\n\nSagt, was würdet Ihr davon halten, mein Ersatzgrabekumpel zu werden?", sourceObjective = "Geht auf ein Grabungsabenteuer mit Myrrit.", completion = "Ihr seid ein guter Partner. Wir sollten öfter gemeinsam graben. Und uns einen Namen für unser Grabungsteam ausdenken! Etwas wie... Grabies? Buddlies? Ich überlege mir etwas.\n\nIch weiß nicht, wann meine alte Freundin wieder Zeit hat, also freue ich mich, Euch getroffen zu haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[74877] = { id = 74877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beste Freunde", description = "Es hat wirklich Spaß gemacht, mit Euch zu graben. Ehrlich! Bitte versteht das nicht falsch, aber... ich vermisse meine beste Freundin.\n\nIch nehme es ihr nicht übel, dass sie beschäftigt ist. Sie war entführt und sie ist die Prinzessin! Ich weiß, dass sie nicht viel Zeit hat. Ich wünschte nur... \n\n...ich weiß nicht.\n\nVielleicht wünsche ich mir einfach, dass alles wieder so wird wie früher, als sie mit mir graben wollte.", sourceObjective = "Bereitet eine Grabung für Myrrit und Effervesta vor.", progress = "Das ist Effervestas Lieblingssnack...", completion = "Vielleicht hat sie es vergessen oder sie ist noch beschäftigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[74878] = { id = 74878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alte Freunde, liebe Freunde", description = "Ich will meine beste Freundin nicht aufgeben, aber was ist, wenn sie nicht mehr mit mir befreundet sein will?\n\nWir waren Grabekumpel, seit wir ganz klein waren. Vielleicht ist es mir wichtiger als ihr.\n\nWas soll ich überhaupt sagen?", sourceObjective = "Helft Myrrit, mit Effervesta zu sprechen.", progress = "Warum ist diese Unterhaltung so schwierig?", completion = "Ich glaube, mir geht es jetzt besser, {name}.\n\nWir können immer noch beste Freunde sein, auch wenn wir nicht mehr zusammen graben. Und ich habe neue Freunde, mit denen ich graben kann.\n\nIch bin froh, dass das nicht mehr auf mir lastet.", sourceObjectiveStatus = "unverified-source-field" }
quests[74879] = { id = 74879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ätzendes Gegengewicht" }
quests[74880] = { id = 74880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tagebucheintrag: Relikte", description = "<Diese uralte Seite ist in umgebender Magie gebunden und in einem alten drakonischen Dialekt verfasst.>\n\n<Schuppenkommandanten könnten großes Interesse an dem Inhalt dieses Dokuments haben.>", sourceObjective = "Sammelt einen Tagebucheintrag.", progress = "Konntet Ihr irgendetwas von Interesse finden, {name}?", completion = "Ich meine, mich daran zu erinnern, dass Ebyssian vom Hammer von Khaz'goroth gesprochen hat und davon, wie dieser verwendet wurde, um ihn von Verderbnis zu reinigen.\n\nDa er bei uns nicht funktioniert hat, kann ich nur davon ausgehen, dass ich nie verderbt wurde. Ich betrachte das als Erfolg!\n\nDanke für die Information, {name}. Ich werde das unserer Sammlung hinzufügen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[74882] = { id = 74882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallkreisel - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[74883] = { id = 74883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tagebucheintrag: Die Horte", description = "<Diese uralte Seite ist in umgebender Magie gebunden und in einem alten drakonischen Dialekt verfasst.>\n\n<Schuppenkommandanten könnten großes Interesse an dem Inhalt dieses Dokuments haben.>", sourceObjective = "Findet einen Tagebucheintrag.", progress = "Habt Ihr noch weitere Tagebucheinträge von Adamanthia gefunden?", completion = "Das ist einfach unheimlich. Ich weiß, was passiert ist, und doch läuft es mir eiskalt die Schuppen herunter.\n\nIch werde unserer Sammlung ein übersetztes Exemplar beifügen lassen, damit andere es auch lesen können.\n\nIch frage mich wirklich, auf wessen Seite diese Adamanthia eigentlich stand.", sourceObjectiveStatus = "unverified-source-field" }
quests[74889] = { id = 74889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalderarundflug", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[74892] = { id = 74892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Älteste der Zaqali" }
quests[74896] = { id = 74896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tagebucheintrag: Stille", description = "<Diese uralte Seite ist in umgebender Magie gebunden und in einem alten drakonischen Dialekt verfasst.>\n\n<Schuppenkommandanten könnten großes Interesse an dem Inhalt dieses Dokuments haben.>", sourceObjective = "Findet einen Tagebucheintrag.", progress = "Das könnte sich als äußerst aufschlussreich erweisen.", completion = "Sie haben uns also selbst vor den anderen Aspekten geheim gehalten. Malygos wusste davon, doch von dem, was ich so gehört habe, könnte er genauso von allem losgelöst sein wie Neltharion.\n\nIch werde diesen Tagebucheintrag unserer übersetzten Sammlung hinzufügen lassen. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[74899] = { id = 74899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalderarundflug - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[74900] = { id = 74900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empfangsstein: Letzte Warnung", description = "<Dieser Empfangsstein birgt uralte Worte von Neltharion in einem alten drakonischen Dialekt.>\n\n<Die Dracthyr-Schuppenkommandanten könnten großes Interesse an dem Inhalt dieses Dokuments haben.>", sourceObjective = "Findet einen Empfangsstein.", progress = "Was habt Ihr entdeckt?", completion = "Oh... An den Tonfall kann ich mich noch erinnern.\n\nIch bekomme langsam das Gefühl, dass Adamanthia eine Grenze überschritten hatte, ab der es kein Zurück mehr für sie gab.\n\nIch werde die Übersetzung dieses Steins unseren Transkripten hinzufügen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[74901] = { id = 74901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sendestein: Protest", description = "<Dieser Sendestein birgt uralte Worte in einem alten drakonischen Dialekt, die Adamanthia einst an Neltharion gerichtet hat.>\n\n<Schuppenkommandanten könnten großes Interesse an dem Inhalt dieses Dokuments haben.>", sourceObjective = "Findet einen Sendestein.", progress = "Was habt Ihr entdeckt?", completion = "Schön, einen schwarzen Drachen zu sehen, der sich für uns einsetzt, auch wenn es etwas zu spät dafür war.\n\nIch frage mich, was dieses \"Aberrus\" ist. Wenn es sich dabei um einen weiteren Ort handelt, an dem Dracthyr gefangen gehalten wurden, werden wir ihn finden müssen.\n\nIch werde das den übersetzten Aufzeichnungen beifügen lassen. Ihr solltet Euch das mal anschauen, während Ihr mehr davon auftreibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[74902] = { id = 74902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sendestein: Erster Bericht", description = "<Dieser Sendestein birgt uralte Worte in einem alten drakonischen Dialekt, die Adamanthia einst an Neltharion gerichtet hat.>\n\n<Schuppenkommandanten könnten großes Interesse an dem Inhalt dieses Dokuments haben.>", sourceObjective = "Findet einen Sendestein.", progress = "Was habt Ihr entdeckt?", completion = "Sie wussten, dass wir nicht gebrochen waren.\n\nSIE WUSSTEN ES.\n\nDas wussten wir vermutlich bereits, aber es so zu lesen... Es fühlt sich einfach so an, als würde noch mehr Öl ins Feuer gegossen werden.\n\nIch danke Euch trotzdem, dass Ihr uns das gebracht habt. Ich werde es übersetzen und den Aufzeichnungen beifügen lassen, damit alle anderen es auch lesen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[74903] = { id = 74903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sendestein: Die Gefangene", description = "<Dieser Sendestein birgt uralte Worte in einem alten drakonischen Dialekt, die Adamanthia einst an Neltharion gerichtet hat.>\n\n<Schuppenkommandanten könnten großes Interesse an dem Inhalt dieses Dokuments haben.>", sourceObjective = "Findet einen Sendestein.", progress = "Was habt Ihr entdeckt?", completion = "Hm? Wenn das stimmt, dann war Raszageth die ganze Zeit über wach, während wir in Stasis waren.\n\nDas erklärt ihren Wahnsinn. Was nicht heißt, dass ich ihr oder ihren Methoden plötzlich zustimme, aber jeder, der für mehrere zehntausend Jahre in einem Loch ohne viel Licht gefangen ist, würde wohl oder übel wahnsinnig werden.\n\nIch werde die übersetzte Version den Transkripten hinzufügen lassen, die wir ausgegeben haben. Habt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[74905] = { id = 74905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forscher unter Feuer" }
quests[74906] = { id = 74906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forscher unter Feuer" }
quests[74908] = { id = 74908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Abenteuer", description = "Katalogisiererin Daela ist hier, um Orte der Wunder und Mysterien zu untersuchen. Der Himmelfuchsbau und die Kaldera der Heiler sehen vielversprechend aus.\n\nIhre Quests abzuschließen wird ihre Gesandtenaufgaben heute freischalten. Morgen könnt Ihr die Gesandtenaufgaben anderer Fraktionen freischalten.", sourceObjective = "Sprecht mit Katalogisiererin Daela.", completion = "Faszinierend! Wir müssen unsere nächsten Schritte sorgfältig planen. Ich gebe Euch detaillierte Anweisungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[74909] = { id = 74909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Fänge", description = "Turik ist hier, um die Reichtümer der See vor der Verbotenen Insel im Namen der Tuskarr von Iskaara zu untersuchen.\n\nDiese Quest abzuschließen, wird seine Gesandtenaufgaben heute freischalten. Morgen könnt Ihr die Gesandtenaufgaben anderer Fraktionen freischalten.", sourceObjective = "Sprecht mit Turik.", completion = "Die Fische beißen heute wirklich gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[74910] = { id = 74910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Gegner", description = "Geschichtenwahrerin Ashekh ist hier, um nach Feinden der Maruuk Ausschau zu halten.\n\nDiese Quest abzuschließen, wird ihre Gesandtenaufgaben heute freischalten. Morgen könnt Ihr die Gesandtenaufgaben anderer Fraktionen freischalten.", sourceObjective = "Sprecht mit Geschichtenwahrerin Ashekh.", completion = "Lasst mich die Stärke unserer Feinde einschätzen. Es gibt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[74911] = { id = 74911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Horizonte", description = "Kraxxus repräsentiert die Stärke des Valdrakkenabkommens hier auf der Verbotenen Insel.\n\nDiese Quest abzuschließen, wird seine Gesandtenaufgaben heute freischalten. Morgen könnt Ihr die Gesandtenaufgaben anderer Fraktionen freischalten.", sourceObjective = "Sprecht mit Kraxxus.", completion = "Willkommen auf der Verbotenen Insel, mein Freund!", sourceObjectiveStatus = "unverified-source-field" }
quests[74912] = { id = 74912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharions Vermächtnis", description = "<Als Ihr in den gesprungenen Titanenedelstein starrt, hallt eine Stimme durch Euren Kopf.>\n\n{name}! Hier spricht Nozdormu. \n\nEs ist Zeit, das Vermächtnis Eures Erschaffers Neltharion zu tilgen. \n\nIhr haltet ein wichtiges Stück des Artefakts, mit dem Neltharion einst Euch und alle Dracthyr kontrollierte.\n\nTrefft mich in Valdrakken. Wir haben viel zu besprechen.", sourceObjective = "Trefft Nozdormu in Valdrakken.", completion = "Ich danke Euch für Euer Kommen. Ich habe diesen Moment schon eine ganze Weile vorbereitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[74913] = { id = 74913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerung an ein Artefakt", description = "Glutthal half mir, den Schwurbinder zu finden. Das war das Artefakt, mit dem Neltharion Euch alle kontrollierte.\n\nIch habe die Zeitlinie durchforstet, um herauszufinden, wie es gefertigt wurde, um ein Gegenstück zu schmieden, das Eure Art beschützt.\n\nDer Edelstein, den Ihr gefunden habt, ist genau der Schlüssel, den ich für den nächsten Schritt in meinen Studien brauche.\n\nIhr und ich sollten uns in der Zaralekhöhle treffen, wo Ihr einst um den zerbrochenen Schwurbinder kämpftet.\n\nDort werden wir die Geheimnisse enthüllen, die wir für das Schmieden unserer eigenen Waffe gegen die Tyrannei brauchen.", sourceObjective = "Trefft Nozdormu in der Zaralekhöhle.", completion = "Ihr haltet die Erinnerungen, wie man das Gegenstück zum Schwurbinder schmiedet.\n\nEs ist an der Zeit, dass Ihr diesen Weg beschreitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[74923] = { id = 74923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man braucht ein Dorf, um ein Artefakt herzustellen", description = "Ihr müsst nun aufbrechen und Hilfe suchen, um die nötigen Komponenten für das Schmieden eines neuen Handschuhs herzustellen.\n\nEssenz der Ordnung ist normalerweise nicht leicht zu finden, aber die Erinnerungen, die Ihr besitzt, werden Euch erlauben, sie an vielen Orten zu finden.\n\nDieser neue Handschuh wird Eure Verbündeten und Eure Gemeinschaft ermächtigen... und aus diesem Grund werdet Ihr die Hilfe anderer brauchen.\n\nNehmt die Erinnerungen, die Ihr gefunden habt, und nutzt sie, um andere zu lehren, diese Teile herzustellen.", sourceObjective = "Nutzt die uralten Erinnerungen, um Euch oder anderen beizubringen, die Teile für Euer neues Artefakt herzustellen.\n\nIhr müsst Arbeitsaufträge platzieren, um die Komponenten von Euren Verbündeten zu erhalten.", progress = "Habt Ihr alle Gegenstände gefunden? Ihr werdet die Hilfe anderer Abenteurer brauchen, um alle Stücke herzustellen.", completion = "Gute Arbeit! Ihr habt viele Mühen auf Euch genommen, um diese Teile herzustellen.\n\nNun müssen wir die letzte Komponente finden, die alles vereint.\n\nDie Essenz des ersten Aspekts der schwarzen Drachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[74924] = { id = 74924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nasz'uro, das entfesselte Vermächtnis", description = "Durch meine Forschungen habe ich die letzte Komponente gefunden, durch die dieses Artefakt ein wahres Gegenstück zum Schwurbinder wird.\n\nDie Essenz von Neltharion.\n\nUnd hier kann ich den Dracthyr endlich helfen. Wir werden zum Mahlstrom reisen und Zeugen seiner letzten Momente werden.\n\nMit seiner Essenz werden wir endlich Euer Artefakt vollenden: Nasz'uro, das entfesselte Vermächtnis.\n\nSprecht mit mir, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Nozdormu, um zum Mahlstrom zu reisen und Neltharions Niederlage zu erleben.", completion = "Euer Artefakt ist nun vollständig. Führt es im Wissen, dass niemand je wieder die {race} kontrollieren wird. Euer Schicksal gehört allein Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[74925] = { id = 74925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalderarundflug - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[74939] = { id = 74939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwefelhast", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[74942] = { id = 74942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmutzige Hinterlassenschaften", description = "Habt Ihr das gesehen? Einige Schleime hinterlassen kleine Dreckhaufen. Hmm...\n\nMelly stellt Zeugs aus allem Möglichen her. Meint Ihr, sie könnte den Dreck benutzen, um Tempo zu helfen? Ich wette, sie kann das.", sourceObjective = "Sammelt Zeitschmutz.", progress = "Zeitschmutz! Ich habe gerade einen Lauf.", completion = "Sehr schön! Ich gebe sie Melly. Zusammen mit meiner Liste sagenhafter Schleimbegriffe.", sourceObjectiveStatus = "unverified-source-field" }
quests[74943] = { id = 74943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwefelhast - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[74944] = { id = 74944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwefelhast - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[74945] = { id = 74945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guanitgambit" }
quests[74946] = { id = 74946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ort der Zuflucht", description = "Als Erstes müssen wir die anderen einholen, die geflohen sind, während Bovan sie verteidigt hat. Hoffentlich haben Bovan und die anderen Krieger sich wieder mit ihnen zusammengeschlossen.\n\nDiese Tomul sagt, dass die Tauren vermutlich in einem verlassenen Dorf im Südosten Zuflucht gesucht haben.\n\nIhre Argumente sind schlüssig, aber das wäre auch der perfekte Ort für eine Falle.\n\n{name}, ich weiß, dass Ihr Euch für sie verbürgt, also werde ich ihr vorerst vertrauen.\n\nHoffen wir, dass dieses Vertrauen gerechtfertigt ist.", sourceObjective = "Trefft Baine und Tomul bei Toghusuq.", completion = "Die gute Nachricht ist, dass wir die anderen Tauren gefunden haben.\n\nDie schlechte ist, dass dieser Bovan, den er sucht, nicht hier ist.\n\nUnd die empörende Nachricht ist, dass mich jeder tot sehen will.", sourceObjectiveStatus = "unverified-source-field" }
quests[74948] = { id = 74948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneck was in dir steckt: Amethystweichschale", description = "Ich rieche eine Schnecke bei Euch, doch irgendetwas ist komisch. Haltet Ihr mich hin?\n\nViele wissen das nicht, doch Schnecken sind besonders anfällig für Gruppenzwang. Zeigt mir die Wunderschnecke, die Ihr da habt. Vielleicht können wir Schleimer dadurch etwas inspirieren.", sourceObjective = "Beschwört eine Amethystweichschale der maximalen Kamphaustierstufe und zeigt sie Briggul.", completion = "Crok, was für eine Schönheit. Und die kommen aus dem Meer? Ich kann mir nicht vorstellen, dass eine meiner Schnecken all das Salz übersteht. \n\nIch bin sicher, Schleimer ist beeindruckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[74949] = { id = 74949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneck was in dir steckt: Archetyp der Wachsamkeit", description = "Ich rieche eine Schnecke bei Euch, doch irgendetwas ist komisch. Haltet Ihr mich hin?\n\nViele wissen das nicht, doch Schnecken sind besonders anfällig für Gruppenzwang. Zeigt mir die Wunderschnecke, die Ihr da habt. Vielleicht können wir Schleimer dadurch etwas inspirieren.", sourceObjective = "Beschwört einen Archetyp der Wachsamkeit der maximalen Kamphaustierstufe und zeigt sie Briggul.", completion = "Das... ist die seltsamste, schickste Schnecke, die ich je gesehen habe.\n\nWenn Schleimer davon nicht beeindruckt ist, weiß ich nicht, was ihn beeindrucken sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[74950] = { id = 74950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneck was in dir steckt: Schwarzkluftkriecher", description = "Ich rieche eine Schnecke bei Euch, doch irgendetwas ist komisch. Haltet Ihr mich hin?\n\nViele wissen das nicht, doch Schnecken sind besonders anfällig für Gruppenzwang. Zeigt mir die Wunderschnecke, die Ihr da habt. Vielleicht können wir Schleimer dadurch etwas inspirieren.", sourceObjective = "Beschwört einen Schwarzkluftkriecher auf der maximalen Kamphaustierstufe und zeigt ihn Briggul.", completion = "Na, DAS ist eine Schnecke, die eine gute Höhle zu schätzen weiß! Schleimer erkennt sich da bestimmt wieder.\n\nIch mich auf jeden Fall.", sourceObjectiveStatus = "unverified-source-field" }
quests[74951] = { id = 74951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimmerslalom", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[74952] = { id = 74952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneck was in dir steckt: Mikrolicid", description = "Ich rieche eine Schnecke bei Euch, doch irgendetwas ist komisch. Haltet Ihr mich hin?\n\nViele wissen das nicht, doch Schnecken sind besonders anfällig für Gruppenzwang. Zeigt mir die Wunderschnecke, die Ihr da habt. Vielleicht können wir Schleimer dadurch etwas inspirieren.", sourceObjective = "Beschwört Mikrolicid auf der maximalen Kamphaustierstufe und zeigt ihn Briggul.", completion = "Keine Ahnung, was an dem Tierchen Mikro sein soll, aber einen Panzer hat er jedenfalls. Andererseits sind die meisten Schnecken ziemlich mikro neben Schleimer!", sourceObjectiveStatus = "unverified-source-field" }
quests[74953] = { id = 74953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwer wiegt die Krone", description = "Ich war wirklich traurig, als Effervesta nicht kam, wie sie versprochen hatte.\n\nAber ich verstehe, dass sie beschäftigt ist, immerhin war sie entführt und hat so viele Pflichten. Ich nehme es ihr nicht übel.\n\nIch möchte ihr sagen, wie viel mir diese Zeit bedeutet hat, als wir klein waren, und dass ich für sie da bin, wenn sie mich braucht. Dann weiß sie immerhin, dass ich noch da bin.\n\nKönnt Ihr mir helfen, lange genug ihre Aufmerksamkeit zu erregen, damit ich sagen kann, was ich sagen muss?", sourceObjective = "Helft dabei, etwas Zeit zu schaffen, damit Myrrit mit Effervesta reden kann.", progress = "Ich will sie nicht stören...", completion = "Jetzt, wo ich sie hier habe, weiß ich nicht, was ich sagen soll!", sourceObjectiveStatus = "unverified-source-field" }
quests[74954] = { id = 74954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimmerslalom - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[74956] = { id = 74956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimmerslalom - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[74959] = { id = 74959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneck was in dir steckt: Schlickmuschelschlurfer", description = "Ich rieche eine Schnecke bei Euch, doch irgendetwas ist komisch. Haltet Ihr mich hin?\n\nViele wissen das nicht, doch Schnecken sind besonders anfällig für Gruppenzwang. Zeigt mir die Wunderschnecke, die Ihr da habt. Vielleicht können wir Schleimer dadurch etwas inspirieren.", sourceObjective = "Beschwört einen Schlickmuschelschlurfer der maximalen Kampfhaustierstufe und zeigt ihn Briggul.", completion = "Manche Leute sehen einen Schlickmuschelschlurfer und fragen sich, was so besonders daran ist. Doch ich, ich weiß die einfachen Dinge zu schätzen. Darin lässt sich auch Schönheit finden.\n\nSchleimer würde mir da bestimmt zustimmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[74960] = { id = 74960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneck was in dir steckt: Räuberischer Helicid", description = "Ich rieche eine Schnecke bei Euch, doch irgendetwas ist komisch. Haltet Ihr mich hin?\n\nViele wissen das nicht, doch Schnecken sind besonders anfällig für Gruppenzwang. Zeigt mir die Wunderschnecke, die Ihr da habt. Vielleicht können wir Schleimer dadurch etwas inspirieren.", sourceObjective = "Beschwört einen räuberischen Heliciden der maximalen Kampfhaustierstufe und zeigt ihn Briggul.", progress = "Zeigt mir die Schnecke! Verhelfen wir Schleimer zu seinem besten schleimigen Selbst.", completion = "Räuberisch, wie? Haltet das Vieh einfach von meinen Eimern fern. Ich kann keine Unfälle gebrauchen. Nicht schon wieder.\n\n<Briggul starrt qualvollen Blickes in die Ferne.>\n\nAber ja, ich bin mir sicher, dass Schleimer den Kampfgeist schon spürt.", sourceObjectiveStatus = "unverified-source-field" }
quests[74961] = { id = 74961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneck was in dir steckt: Prismatische Weichschale", description = "Ich rieche eine Schnecke bei Euch, doch irgendetwas ist komisch. Haltet Ihr mich hin?\n\nViele wissen das nicht, doch Schnecken sind besonders anfällig für Gruppenzwang. Zeigt mir die Wunderschnecke, die Ihr da habt. Vielleicht können wir Schleimer dadurch etwas inspirieren.", sourceObjective = "Beschwört eine prismatische Weichschale der maximalen Stufe und zeigt sie Briggul.", completion = "Prismatisch, wie? Das ist doch nur hochgestochen für schöne Farben, oder? Nun, bei dieser Schnecke passt der Name jedenfalls. Ich hoffe nur, das Schleimer nicht denkt, er müsse sich ein-SCHLEIMEN. Haha! \n\nEr ist, finde ich, so schon hübsch genug.", sourceObjectiveStatus = "unverified-source-field" }
quests[74962] = { id = 74962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneck was in dir steckt: Rapanaschnecke", description = "Ich rieche eine Schnecke bei Euch, doch irgendetwas ist komisch. Haltet Ihr mich hin?\n\nViele wissen das nicht, doch Schnecken sind besonders anfällig für Gruppenzwang. Zeigt mir die Wunderschnecke, die Ihr da habt. Vielleicht können wir Schleimer dadurch etwas inspirieren.", sourceObjective = "Beschwört eine Rapanaschnecke der maximalen Kamphaustierstufe und zeigt sie Briggul.", completion = "Lasst Euch von der nicht täuschen, {name}. Ich spüre die Schale eines Killers. Hoffentlich inspiriert das Schleimer mehr, als dass es ihn verschreckt!", sourceObjectiveStatus = "unverified-source-field" }
quests[74963] = { id = 74963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneck was in dir steckt: Rostschnecke", description = "Ich rieche eine Schnecke bei Euch, doch irgendetwas ist komisch. Haltet Ihr mich hin?\n\nViele wissen das nicht, doch Schnecken sind besonders anfällig für Gruppenzwang. Zeigt mir die Wunderschnecke, die Ihr da habt. Vielleicht können wir Schleimer dadurch etwas inspirieren.", sourceObjective = "Beschwört eine Rostschnecke der maximalen Kamphaustierstufe und zeigt sie Briggul.", completion = "Oh! Rostig wie in rostfarben. Ich habe mich gefragt, was Ihr mit der Kleinen angestellt habt. Hatte fast schon Sorgen um Schleimer!\n\nPuh, was für eine Erleichterung.", sourceObjectiveStatus = "unverified-source-field" }
quests[74964] = { id = 74964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneck was in dir steckt: Finchen die Schnecke", description = "Ich rieche eine Schnecke bei Euch, doch irgendetwas ist komisch. Haltet Ihr mich hin?\n\nViele wissen das nicht, doch Schnecken sind besonders anfällig für Gruppenzwang. Zeigt mir die Wunderschnecke, die Ihr da habt. Vielleicht können wir Schleimer dadurch etwas inspirieren.", sourceObjective = "Beschwört Finchen die Schnecke auf der maximalen Kamphaustierstufe und zeigt sie Briggul.", progress = "Zeigt mir die Schnecke! Verhelfen wir Schleimer zu seinem besten schleimigen Selbst.", completion = "Schaut Euch die Schale von der an! Und Ihr meintet, ein Kind hätte sie Euch gegeben?\n\nGut, dass sie in Euren Händen gelandet ist! Blagen verhalten sich gegenüber Schnecken oft... fragwürdig.", sourceObjectiveStatus = "unverified-source-field" }
quests[74965] = { id = 74965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneck was in dir steckt: Schnecki", description = "Ich rieche eine Schnecke bei Euch, doch irgendetwas ist komisch. Haltet Ihr mich hin?\n\nViele wissen das nicht, doch Schnecken sind besonders anfällig für Gruppenzwang. Zeigt mir die Wunderschnecke, die Ihr da habt. Vielleicht können wir Schleimer dadurch etwas inspirieren.", sourceObjective = "Beschwört Schnecki auf der maximalen Kamphaustierstufe und zeigt ihn Briggul.", progress = "Zeigt mir die Schnecke! Verhelfen wir Schleimer zu seinem besten schleimigen Selbst.", completion = "\"Schnecki\" ist ein Name, mit dem ich mich anfreunden kann. Vielleicht ist das ja Schleimers verloren geglaubter Cousin!\n\n<Briggul schaut sich den Schneckenvorfahren nochmal an.>\n\nHmm. Vielleicht... sehr lange verloren geglaubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[74966] = { id = 74966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneck was in dir steckt: Seidenperlenschnecke", description = "Ich rieche eine Schnecke bei Euch, doch irgendetwas ist komisch. Haltet Ihr mich hin?\n\nViele wissen das nicht, doch Schnecken sind besonders anfällig für Gruppenzwang. Zeigt mir die Wunderschnecke, die Ihr da habt. Vielleicht können wir Schleimer dadurch etwas inspirieren.", sourceObjective = "Beschwört eine Seidenperlenschnecke der maximalen Kamphaustierstufe und zeigt sie Briggul.", progress = "Zeigt mir die Schnecke! Verhelfen wir Schleimer zu seinem besten schleimigen Selbst.", completion = "Schaut Euch nur an, wie die sich bewegt! Der Schleim der Seidenperlenschnecke hat eine ganz besondere Konsistenz.\n\nBin mir nicht sicher, ob Schleimer da viel zu lernen hat, aber Ihr dafür umso mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[74967] = { id = 74967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneck was in dir steckt: Spindelschnecke", description = "Ich rieche eine Schnecke bei Euch, doch irgendetwas ist komisch. Haltet Ihr mich hin?\n\nViele wissen das nicht, doch Schnecken sind besonders anfällig für Gruppenzwang. Zeigt mir die Wunderschnecke, die Ihr da habt. Vielleicht können wir Schleimer dadurch etwas inspirieren.", sourceObjective = "Beschwört eine Spindelschnecke der maximalen Kamphaustierstufe und zeigt sie Briggul.", completion = "Ich bin mir sicher, dass Schleimers Fähigkeiten bald schon SPINDEL-erregende Höhen erreichen! Haha!\n\n<Briggul wischt sich eine Freudenträne aus dem Auge.>\n\nDen sollte ich mir fürs nächste Rennen aufheben. Die anderen Trainer werden sich nicht mehr einkriegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[74968] = { id = 74968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schneck was in dir steckt: Wusch", description = "Ich rieche eine Schnecke bei Euch, doch irgendetwas ist komisch. Haltet Ihr mich hin?\n\nViele wissen das nicht, doch Schnecken sind besonders anfällig für Gruppenzwang. Zeigt mir die Wunderschnecke, die Ihr da habt. Vielleicht können wir Schleimer dadurch etwas inspirieren.", sourceObjective = "Beschwört Wusch auf der maximalen Kamphaustierstufe und zeigt ihn Briggul.", completion = "Das... Das ist WUSCH! Die legendäre Rennschnecke vom Hochberg!\n\nCrok verdammt, das muss ich meinem Cousin Bummbumm erzählen. Was für eine Ehre. Und sicherlich auch für Schleimer.", sourceObjectiveStatus = "unverified-source-field" }
quests[74972] = { id = 74972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loamm-Jagd", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[74975] = { id = 74975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loamm-Jagd - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[74977] = { id = 74977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loamm-Jagd - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[74983] = { id = 74983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Authentische Autorisierung", description = "Die Wichtigkeit dieser Expedition darf nicht unterschätzt werden. Ich versichere Euch, alle Teilnehmer werden in die Geschichte eingehen... zusammen mit mir, versteht sich!\n\nWenn ich eine bemerkenswerte Entdeckung machen kann, wäre mein Vermächtnis als Gelehrter gesichert! Aber was werden wir finden? Eine Kopie von Neltharions Unterschrift? Einen seiner persönlichen Briefe? Ich kann kaum erwarten, etwas zu finden, das ich mit meinen Bewunderern teilen kann. Außerdem brauche ich mehr Bewunderer!\n\nWenn Ihr so freundlich wärt, etwas Denkwürdiges für mich zu finden, werde ich Euch reich entlohnen! Ich kann bezahlen!", sourceObjective = "Findet 10 von Neltharion unterzeichnete Notizen.", progress = "Habt Ihr irgendetwas finden können?", completion = "Was für ein großartiger Fund! Mir wird ganz schwindelig.\n\nOh, ich kann es kaum erwarten, über diese Entdeckung zu schreiben und unsere Erkenntnisse zu veröffentlichen. Wir werden veröffentlichen... oder beim Versuch vergehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[74984] = { id = 74984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Authentische Autorisierung", description = "Die Wichtigkeit dieser Expedition darf nicht unterschätzt werden. Ich versichere Euch, alle Teilnehmer werden in die Geschichte eingehen... zusammen mit mir, versteht sich!\n\nWenn ich eine bemerkenswerte Entdeckung machen kann, wäre mein Vermächtnis als Gelehrter gesichert! Aber was werden wir finden? Eine Kopie von Neltharions Unterschrift? Einen seiner persönlichen Briefe? Ich kann kaum erwarten, etwas zu finden, das ich mit meinen Bewunderern teilen kann. Außerdem brauche ich mehr Bewunderer!\n\nWenn Ihr so freundlich wärt, etwas Denkwürdiges für mich zu finden, werde ich Euch reich entlohnen! Ich kann bezahlen!", sourceObjective = "Findet 3 Exemplare mit wahllosem Gekritzel.", progress = "Habt Ihr irgendetwas finden können?", completion = "Was für ein großartiger Fund! Mir wird ganz schwindelig.\n\nOh, ich kann es kaum erwarten, über diese Entdeckung zu schreiben und unsere Erkenntnisse zu veröffentlichen. Wir werden veröffentlichen... oder beim Versuch vergehen!", sourceObjectiveStatus = "unverified-source-field" }
