quests[74991] = { id = 74991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sind zurück" }
quests[74992] = { id = 74992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brandschutzausrüstung" }
quests[74994] = { id = 74994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hraxians unbeugsamer Wille", sourceObjective = "Ich habe mit der Zeit viel vergessen.\n\nIhr habt mir jetzt schon zweimal geholfen, eine wertvolle Erinnerung wiederzuerlangen.\n\n<Veritistrasz lächelt leicht.>\n\nVielleicht sollte ich Tellywins Angebot, meine Memoiren zu schreiben, annehmen. Und sei es um meiner selbst willen.\n\nIhr habt so viel für mich und diese Leute getan. Ich hoffe, dass ich mich eines Tages dafür revanchieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[74996] = { id = 74996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schwieriges Erbe", sourceObjective = "Redet mit Voraxian und Veritistrasz am Rusza'thar-Vorstoß.", progress = "Es ist immer ein Vergnügen, {name}.", completion = "Danke, dass Ihr hier seid, {name}. Ihr zwei habt mich stark zum Nachdenken gebracht.\n\nIch bleibe vorerst bei Veritistrasz, aber ich freue mich schon auf unsere nächste Begegnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[75018] = { id = 75018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Dunkel", description = "Meine Schwarzkrallen bewachen weiter das Labor, aber ich glaube, wir sind hier fertig, {name}.\n\nWir haben ein paar Kriecherdrachen bei uns, die uns zur Hauptplattform herunterbringen. Von dort aus kommen wir dann weiter nach unten, wo Sarkareth fiel.\n\nIch bin sicher, dass Ebyssian und Glutthal von unserer Anwesenheit profitieren werden.", sourceObjective = "Trefft Euch mit Ebyssian und Glutthal im Raum ganz unten im Labor.", completion = "Gut, dass Ihr es geschafft habt. Ich könnte Eure Hilfe brauchen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[75022] = { id = 75022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vinyeti" }
quests[75023] = { id = 75023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungen von Sindragosa und Malygos", description = "Ich gebe zu, dass ich dieses Phänomen ganz vergessen habe. Blaue Drachen, die einen grausamen Tod erleiden, hinterlassen von Zeit zu Zeit etwas nachklingende arkane Energie.\n\nDiese Energien können sich auf verschiedene Weisen manifestieren, wenn die Essenzen zur Ruhe gebettet werden.\n\nGlücklicherweise ist es überaus einfach, sie zu bannen. Wedelt einfach irgendetwas durch die Energie und schon zerstreut sie sich.\n\nIch werde die Essenzen von Sindragosa und Malygos in diesem Grabstein untersuchen, während Ihr Euch darum kümmert.", sourceObjective = "Bannt die nachklingenden Erinnerungen von Sindragosa und Malygos.", progress = "Wie seltsam, dass diese Erinnerungen überdauern...", completion = "Das sollte es gewesen sein, wobei es merkwürdig ist, dass nicht alle Erinnerungen so schnell gebannt wurden, wie ich gehofft hatte...\n\nLasst uns mit Kalecgos sprechen, um ihn wissen zu lassen, dass wir das im Auge behalten sollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[75024] = { id = 75024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Listige Käfer", description = "Käfer kriechen durch unseren Unterstützungshort! Einige davon fressen nun Teile der zerstörten Infusoren und werden dadurch stärker. Wir versuchen, sie zu zerdrücken, aber sie bleiben nicht zerdrückt.\n\nJetzt ist es schwierig, sie loszuwerden, aber wir haben einen Plan. Wir haben herausgefunden, dass sie durch Treffer mit Teilen von kaputten Infusoren sie wieder geschwächt werden!\n\nWürdet Ihr uns dabei helfen, diese energieerfüllten Käfer loszuwerden?", sourceObjective = "Besiegt 12 energieerfüllte Käfer.", progress = "Habt Ihr diese Käfer bereits vertreiben können?\n\nIch wusste, dass uns bei unserer Rückkehr auf die Insel neue Tiere begegnen würden, aber so habe ich mir das nicht vorgestellt. Und ich habe langsam genug davon, Insektenstiche zu behandeln.", completion = "Großartige Arbeit! Jetzt wird es leichter für uns sein, den Unterstützungshort zurückzuerobern.", sourceObjectiveStatus = "unverified-source-field" }
quests[75025] = { id = 75025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein guter Tag zum Rollen", description = "Ich habe eine... ungewöhnliche Bitte an Euch. Ich brauche Hilfe mit einigen Eichhörnchen. Primalisten haben sie verderbt, und das hat sie instabil gemacht!\n\nIch weiß aber, wie wir sie abkühlen. Schnee! Wenn Ihr diese Kreaturen in einen großen Schneeball aufrollen könnt, werden sie abkühlen, während der Schnee schmilzt. Genial, oder?\n\nKönnt Ihr mir helfen? Ich kann mich nicht konzentrieren oder meine Aufzeichnungen abschließen, und ich habe nicht die Zeit, ausdrucksvollere Prosa zu schreiben. Wenn Euch sonst nichts wichtig ist, denkt an den Verlust für die Literatur!", sourceObjective = "Rettet 14 überladene Kleintiere.", completion = "Danke für Eure Hilfe! Ich kann mich endlich etwas entspannen.\n\nIch werde Euch danken, indem ich Eure Taten in meine Aufzeichnungen aufnehme. Ich werde vielleicht auch einen Charakter in mein nächstes Buch aufnehmen, der von Euch inspiriert ist. Ich werde behaupten, dass es ein eigenständiger Charakter ist, aber wir werden beide insgeheim wissen, dass es Ihr seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[75026] = { id = 75026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf in die höchsten Höhen!", description = "Tuskarrkinder lieben Drachen wirklich! Ich habe ein paar von ihnen vor dem Morqutdorf damit herumrennen sehen. Ich habe auch einige Drachen in Bäumen stecken sehen.\n\nKönntet Ihr mir einen Gefallen tun? Werft ein Lasso nach diesen Drachen und zieht sie herunter. Dabei werden sie zwar kaputtgehen, aber die Kinder können sie bestimmt reparieren. Wer weiß? Vielleicht lernen sie dann ja, vorsichtiger zu sein.", sourceObjective = "Sammelt 12 Drachenstücke.", completion = "Fantastische Arbeit! Wenn sie ihre Drachen reparieren, sind die Kinder beschäftigt und bringen sich nicht in Schwierigkeiten... für eine Weile zumindest.\n\nDas ist gut. Diese Kinder schaffen es überall hin.", sourceObjectiveStatus = "unverified-source-field" }
quests[75028] = { id = 75028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerbrochen", description = "Glutthal trauert. Tatsächlich trauert sie schon seit einer ganzen Weile um Sarkareth.\n\nSie muss selbst entscheiden, wie es weitergeht. Wir können sie auf ihrem Weg nur unterstützen.\n\nHier im ganzen Raum sind einzelne Splitter von Sarkareths Signet verteilt. Könnt Ihr sie einsammeln? Sie wird diese Geste sicher zu schätzen wissen.", sourceObjective = "Sammelt die Splitter von Sarkareths Signet ein.", progress = "<Glutthal ist noch nicht in der Stimmung zu sprechen.>", completion = "<Glutthal blickt auf, als Ihr Euch nähert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[75029] = { id = 75029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neu geschmiedetes Vermächtnis", description = "Trauer ist eine schmerzvolle Last. Es wärmt mir das Herz, zu sehen, wie Glutthal ihre Trauer überwindet und sich auf ihr Volk konzentriert. Der Schmerz über ihren Verlust wird mit der Zeit abklingen.\n\nWir müssen Alexstrasza und die anderen darüber informieren, was sich hier zugetragen hat... und über die Zukunft des schwarzen Drachenschwarms.\n\nNach allem, was Ihr für unsere Chance auf eine Zukunft geleistet habt, würde ich Euch gerne dort sehen.", sourceObjective = "Trefft Ebyssian beim Sitz der Aspekte in Valdrakken.", completion = "Ein neuer Pfad. Aber einer, den ich gerne beschreite.", sourceObjectiveStatus = "unverified-source-field" }
quests[75030] = { id = 75030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallkatastrophe!" }
