quests[75042] = { id = 75042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwefelsprint - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[75043] = { id = 75043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwefelsprint - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[75050] = { id = 75050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein vielschichtiger Pakt", description = "Als der Sturm über der Insel tobte, sammelte ich Verbündete für unsere spätere Rückkehr. Ich will sicherstellen, dass sie alles haben, was sie brauchen, aber ich kann nicht alle von ihnen persönlich willkommen heißen.\n\nWürdet Ihr mir zur Hand gehen, {name}? Könntet Ihr sicherstellen, dass sie alles Nötige haben? Wir haben nur wenige Vorräte anzubieten und noch weniger helfende Hände.\n\nIch kann zumindest meine Dankbarkeit anbieten. Bitte dankt ihnen in meinem Namen persönlich.", sourceObjective = "Sprecht mit den neu eingetroffenen Bewohnerin des Morqutdorfs.", completion = "Ich muss Euch ebenfalls danken, {class}. Unsere Verbündeten sind aus vielen Gründen auf die Insel gekommen. Ihre Freundlichkeit beschämt mich.\n\nJetzt müssen wir Nägel mit Köpfen machen und alles dafür tun, dass dieser Ort sicher ist und erblühen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[75058] = { id = 75058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An der Speerspitze der Beschaffung" }
