quests[75128] = { id = 75128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleimwirtschaft" }
quests[75145] = { id = 75145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach der Asche", description = "Wir haben getan, was wir konnten. Wir werden zurückkehren, um ihnen beim Wiederaufbau zur Hand zu gehen, aber für den Moment... braucht das Volk der Loamm erst mal Zeit zu trauern.\n\nAlexstrasza muss darüber informiert werden, was hier heute geschah. Sie muss gewarnt werden, was auf den Dracheninseln entfesselt wurde.\n\nWir treffen Euch am Sitz der Aspekte.", sourceObjective = "Trefft Ebyssian beim Sitz der Aspekte in Valdrakken.", progress = "Alle müssen erfahren, was passiert ist.\n\nNur so können wir uns vielleicht auf den Schaden vorbereiten, der da kommen mag.", completion = "Mehr können wir momentan nicht tun.\n\nSabellian, Furorion und ich müssen unsere nächsten Schritte planen, während wir unsere Rückkehr nach Zaralek vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[75148] = { id = 75148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Techniken", description = "Ich habe Geschichten gehört, dass die Djaradin ihre Waffen mit Magie schmieden, die so heiß ist, dass sie das Metall tatsächlich in Lava abschrecken können. Lava! Das muss im Vergleich zu der Hitze ihrer Magie wie Eiswasser sein! \n\nIch konnte das jedoch nie selbst bestätigen. Sie verkaufen ihre Waren schließlich nicht einfach auf dem Markt.\n\nIhr wirkt allerdings kampferprobt. Besorgt einige ihrer Waffen für die Schmiede in Loamm, dann sehen wir, ob die Legenden wahr sind, was sagt Ihr?", sourceObjective = "Sammelt 8 lavagehärtete Klingen.", progress = "Es fällt mir schwer, die Geschichten zu glauben, und doch... sie leben schließlich in Magmagruben!", completion = "<Crubus versucht Euch die Klingen abzunehmen, zieht jedoch schnell wieder die Hände zurück und schüttelt sie kräftig.>\n\nAUTSCH! Wie haltet Ihr die einfach so?!\n\nLegt... Legt sie einfach auf den Boden. Ich hole Handschuhe.", sourceObjectiveStatus = "unverified-source-field" }
quests[75149] = { id = 75149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obsidianabhandlungen", description = "Heutzutage ist es nicht verbreitet, aber einen Teil unserer Geschichte haben wir aufgeschrieben... nun, genaugenommen eingraviert. So können wir sie mit unseren Fingern lesen! \n\nFrüher haben wir dafür Tontafeln benutzt, aber die waren spröde zerbrachen leicht. Nicht gut, wenn man Geschichte bewahren will!\n\nWie ich hörte, gravieren die Djaradin ihre wichtigen Texte in Vulkanglas. Wenn sie das schaffen, ohne dabei die Tafeln zu zerbrechen, können wir wohl noch das ein oder andere von ihren Techniken lernen.\n\nBringt einige Proben nach Loamm, damit sie untersucht werden können.", sourceObjective = "Sammelt 10 Obsidiantafeln.", progress = "Den seltsamsten Quellen kann neues Wissen entspringen!", completion = "Faszinierend... Sie mögen wie Grobiane wirken, doch diese Gravuren erfordern eine ruhige und sorgfältige Hand. Und jede Menge Geduld.\n\nMit etwas Glück bekommen wir das auch irgendwann hin, findet Ihr nicht auch?", sourceObjectiveStatus = "unverified-source-field" }
quests[75150] = { id = 75150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Selbstberäucherung", description = "Einige unserer Räucherwerke müssen sehr langsam verbrannt werden, um die richtigen Aromen freizusetzen. Man kann die Temperatur natürlich selbst überprüfen... doch das kann ziemlich nervig werden.\n\nGlücklicherweise habe ich eine Lösung gefunden! Wenn man die Scherben von Feuerelementaren zermahlt und den Staub über das Räucherwerk streut, kann man die Temperatur durch Verzauberungen konstant halten. Vollautomatisch!\n\nEs ist allerdings nicht ganz einfach, an diese Scherben zu kommen. Könntet Ihr einige besorgen und sie meinen Freunden in Loamm bringen?", sourceObjective = "Sammelt 8 ewig brennende Feuerscherben.", progress = "Älteste Honigpelz bringt uns für gewöhnlich einen Vorrat an Scherben mit, wenn sie von einer Jagd zurückkehrt, doch ich würde sie nur ungern so schnell schon wieder damit belästigen.", completion = "Hervorragend! Mit der Ladung sollte ich unser Räucherwerk wochenlang brennen lassen können und am Ende immer noch etwas übrig haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[75151] = { id = 75151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überreste neu verteilen" }
quests[75154] = { id = 75154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal: Morqutinsel", description = "Wir haben nun Zugang zur Verbotenen Insel, und Katalogisiererin Daela wartet dort auf Euch.\n\nSie hat mir eine Nachricht zu einer vielversprechenden Felsnadel in der Nähe des Dorfs geschickt, in dem sie sich aufhält.\n\nMeint Ihr, dort könnte noch ein inaktives Portal sein? Geht hin und findet es raus!", sourceObjective = "Findet des inaktive Portal auf der Morqutinsel der Verbotenen Insel.", progress = "Habt Ihr was gefunden?", completion = "Ich wusste es!", sourceObjectiveStatus = "unverified-source-field" }
quests[75155] = { id = 75155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenflammenlöscher" }
quests[75156] = { id = 75156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stressexpress" }
quests[75162] = { id = 75162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwörung der Elemente" }
quests[75164] = { id = 75164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urfokusse gesucht", progress = "Die großen Fraktionen der Dracheninseln wollen die Ausrüstung ihrer Krieger verbessern.\n\nHabt Ihr zufällig irgendwelche Urfokusse, die Ihr dieser Sache spenden wollt? Die Fraktion, der Ihr spendet, wird Euch dankbar sein.", completion = "Vielen Dank!\n\nSagt mir, welcher großer Fraktion ihr spenden wollt, dann sorge ich dafür, dass sie von Eurer Großzügigkeit erfährt." }
quests[75165] = { id = 75165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konzentrierte Urfokusse gesucht", progress = "Die großen Fraktionen der Dracheninseln wollen die Ausrüstung ihrer Krieger verbessern.\n\nHabt ihr zufällig irgendwelche konzentrierten Urfokusse, die Ihr dieser Sache spenden wollt? Die Fraktion, der Ihr spendet, wird Euch dankbar sein.", completion = "Vielen Dank!\n\nSagt mir, welcher großer Fraktion ihr spenden wollt, dann sorge ich dafür, dass sie von Eurer Großzügigkeit erfährt." }
quests[75166] = { id = 75166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viele Urfokusse gesucht", progress = "Die großen Fraktionen der Dracheninseln wollen die Ausrüstung ihrer Krieger verbessern.\n\nHabt Ihr zufällig irgendwelche Urfokusse, die Ihr dieser Sache spenden wollt? Die Fraktion, der Ihr spendet, wird Euch dankbar sein.", completion = "Vielen Dank!\n\nSagt mir, welcher großer Fraktion ihr spenden wollt, dann sorge ich dafür, dass sie von Eurer Großzügigkeit erfährt." }
quests[75167] = { id = 75167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viele konzentrierte Urfokusse gesucht", progress = "Die großen Fraktionen der Dracheninseln wollen die Ausrüstung ihrer Krieger verbessern.\n\nHabt ihr zufällig irgendwelche konzentrierten Urfokusse, die Ihr dieser Sache spenden wollt? Die Fraktion, der Ihr spendet, wird Euch dankbar sein.", completion = "Vielen Dank!\n\nSagt mir, welcher großer Fraktion ihr spenden wollt, dann sorge ich dafür, dass sie von Eurer Großzügigkeit erfährt." }
quests[75168] = { id = 75168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftraumkontrolle", description = "Wir werden nicht vorankommen, solange diese Schattenflammendrachen uns von oben hier festnageln.\n\nBegebt auch da hoch und holt sie aus der Luft.", sourceObjective = "Tötet Urnachtflammen oder holt sie mit 'Wirbelnder Ansturm' aus der Luft.", progress = "Sie sind nicht die Einzigen, die fliegen können.", completion = "Der Himmel lichtet sich schon etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[75181] = { id = 75181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiwillige Feuerwehr", description = "Wir müssen die Feuer eindämmen, die durch diese Rituale ausgelöst werden.\n\nWir sind zu weit vom Fluss entfernt, um von seinem Wasser Gebrauch zu machen, doch glücklicherweise haben wir zwei... Freiwillige... von außerhalb der Ebenen, die angeblich helfen können. Sie könnten etwas Unterstützung brauchen.\n\nEs geht um einen Goblin und einen Gnom. Findet sie bitte. Ich weiß ihre Hilfe zu schätzen, aber sie brauchen jemanden, der sie anleitet.", sourceObjective = "Verwendet den Wasserelementar, um die Feuer im Durchdringungslager zu löschen.", progress = "Schnell, bevor sie sich weiter ausbreiten.", completion = "Ein nützlicher Trick, so viel steht fest. Würden die beiden doch nur besser miteinander zurechtkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75182] = { id = 75182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwerer Mammutdiebstahl", description = "Die Djaradin haben ein Mammut mit der Ausbeute ihrer Arbeit hier beladen und wollen es zu Fyrakk schicken.\n\nLeitet die Lieferung um. Wir können die Vorräte, die sie gesammelt haben, gut gebrauchen.", sourceObjective = "Steigt auf ein überladenes Mammut und bringt es hinter Eure Linien.", progress = "Sollte nur schwer zu übersehen sein. Die sind schließlich ziemlich groß.", completion = "Ausgezeichnet! Das sollte ihrem Vorhaben eine mammutgroße Beule verpassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[75189] = { id = 75189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je mehr, desto sicherer", description = "Es ist an der Zeit, dass wir uns den anderen Überlebenden anschließen. Ich habe gehört, dass König Graumähne und seine Königswache sich direkt südlich von hier aufhalten sollen.", sourceObjective = "Sprecht mit König Genn Graumähne im Militärviertel.", sourceObjectiveStatus = "unverified-source-field" }
quests[75190] = { id = 75190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abels Fabel", description = "Die meisten von uns haben es lebend hierher geschafft... aber auf dieser Seite der Stadt gibt es auch Worgen.\n\nSobald alle hier eingetroffen sind, werden wir weiter nach Süden ziehen.\n\nDa fällt mir ein: Jemand hat nach Euch gefragt. Ein Mönch, Todd Abel, sagte, er müsste Euch sprechen. Er wirkte besorgt.", sourceObjective = "Redet mit Todd Abel im Militärviertel.", sourceObjectiveStatus = "unverified-source-field" }
quests[75200] = { id = 75200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefenschinderschlächter" }
quests[75203] = { id = 75203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abwesende Freunde", description = "Ich mache mir etwas Sorgen um unsere Königin.\n\nAlexstrasza ist schon seit einiger Zeit nicht mehr hier, weil sie ihre Gedanken sammeln wollte. Ich habe keinen echten Grund zur Sorge, aber nach allem, was geschehen ist, sorge ich mich trotzdem um ihr Wohlbefinden.\n\nBitte verschafft einem alten Drachen etwas Ruhe und findet heraus, ob mit ihr alles in Ordnung ist.", sourceObjective = "Seht nach Alexstrasza.", sourceObjectiveStatus = "unverified-source-field" }
quests[75221] = { id = 75221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rumble-Münze finden", description = "Um diesen Spielautomaten zu verwenden, benötigt Ihr eine Rumble-Münze.\n\nAuf den Dracheninseln sind mehrere davon versteckt. Darüber können wir allerdings später sprechen.\n\nIch habe hier im Gerösteten Geißbock eine Münze versteckt. Wenn Ihr sie findet, gehört sie Euch.\n\nWerft die Rumble-Münze in den Rumble-Automaten und lasst den Spaß beginnen!", sourceObjective = "Findet eine Rumble-Münze im Gerösteten Geißbock und werft sie in den Warcraft Rumble-Automaten.", progress = "<Der Warcraft Rumble-Automat steht vor Euch. Auf einem kleinen Schild steht:>\n\nZum Spielen Rumble-Münze einwerfen.", completion = "<Als Ihr die Münze einwerft, beginnt der lustige, kleine Automat zu poltern und zu klimpern.\n\nIhr habt einen Preis gewonnen!>", sourceObjectiveStatus = "unverified-source-field" }
quests[75222] = { id = 75222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panzerfeuer" }
quests[75223] = { id = 75223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warcraft Rumble-Miniaturen: Neues Aussehen!", description = "<Ihr entdeckt eine in die Folie geritzte Botschaft.>\n\nDiese Warcraft Rumble-Folie kann an einem Warcraft Rumble-Automaten verwendet werden. Verschafft einer Eurer Miniaturen ein neues Aussehen!", sourceObjective = "Geht zum Warcraft Rumble-Automaten in Valdrakken.", completion = "<Der Warcraft Rumble-Automat hat eine Öffnung. Sie hat genau die richtige Größe, um eine Miniatur und eine Warcraft Rumble-Folie einzulegen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[75230] = { id = 75230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versöhnbare Dissidenten", description = "Es ist meine Hoffnung, {name}, dass unsere Arbeit, die Rebellen zu verstehen, uns dazu verhilft, Frieden zu erlangen.\n\nMeine Sorge ist, dass, wenn wir es nicht schaffen, eine Einigung mit Belaphon zu erzielen, die anderen Rebellen sie als Märtyrerin betrachten.\n\nEgal, was geschieht, Ihr habt meine Dankbarkeit für Eure Unterstützung während dieser Rebellion.", sourceObjective = "Hört dem Gespräch zwischen Alexstrasza und Anstifterin Belaphon zu.", completion = "Diese Krise hat uns dazu gebracht, einander besser zu verstehen, und mich dazu, eine bessere Anführerin zu sein.\n\nUnd all das wäre ohne Eure Hilfe nicht möglich gewesen, {name}. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[75232] = { id = 75232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallene Habseligkeiten", description = "<Ihr wickelt Sheridons Habseligkeiten in ein Bündel und verstaut sie in Eurem Rucksack, um sie den Leuten im Lager zu bringen.>", sourceObjective = "Bringt Sheridon Hastles Habseligkeiten zu Erdheilerin Narvra im Lager der Drachenschuppenexpedition in der Zaralekhöhle.\n\nBereitgestellter Gegenstand:", completion = "Oh... Sheridon... Er hat sein Leben für die unsrigen gegeben. Ich... Ich werde sicherstellen, dass seine Familie diese Sachen bekommt.\n\nIch werde den Ort seines Leichnams markieren. Rupert wird ihn dann bergen, damit er eine angemessene Beisetzung bekommt.\n\nVielen Dank. Hier, nehmt das.", sourceObjectiveStatus = "unverified-source-field" }
quests[75233] = { id = 75233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleisch zu Knochen", description = "Wir fanden Skuttog nahe einer Höhle im Norden, er wurde von garstigen Spinnen gebissen. Es sieht aus, als würde seine Haut verknöchern.\n\nIch kann ihn heilen, aber dafür brauche ich Gift von dem Ungeheuer, das ihn gebissen hat. Bitte helft mir.", sourceObjective = "Findet das Gift der Bestie, die Skuttog gebissen hat.", progress = "Bitte beeilt Euch. Er ist schon fast eine Statue.", completion = "Das sollte reichen. Schauen wir mal, ob es funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[75234] = { id = 75234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kratzen und schnüffeln" }
quests[75237] = { id = 75237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westen der Insel", description = "Ihr und Eure Drachen genießt Eure Abenteuer auf der Verbotenen Insel, nicht wahr? \n\nIch habe gehört, dass der Wind im westlichen Teil der Insel heute besonders gut ist. Wollt Ihr es nicht mit ein paar Rennstrecken dort probieren?", sourceObjective = "Fliegt auf den Rennstrecken der westlichen Verbotenen Insel.\n\nBeendet ein beliebiges der beiden fortgeschrittenen oder umgekehrten Rennen, um die Quest sofort abzuschließen.", completion = "Wie es aussieht, habt Ihr beide Euch gut angestrengt. Weiter so!", sourceObjectiveStatus = "unverified-source-field" }
quests[75239] = { id = 75239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anhänger von Fyrakk: Schattenisethal", description = "<Fyrakks Anhänger ist gefallen. Vielleicht spenden die Überreste dieser Bestie denen etwas Trost, deren Lande verwüstet wurden.>", sourceObjective = "Sammelt den Kopf von Schattenisethal ein.", progress = "Das war viel Feuer. Es sind so viele Leute verbrannt.", completion = "Dieses Ungetüm war so wütend. Wut und Zorn, die sich schon Äonen von Jahren bevor mein Volk zum ersten Mal die See befuhr, festgesetzt hatten. Ich kann mir einen so tiefsitzenden Hass nicht einmal vorstellen.\n\nIhr habt all dem zur Ruhe verholfen. Ich danke Euch, {name}, im Namen aller, deren Leben Ihr durch das Erlegen dieser Bestie gerettet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[75244] = { id = 75244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erneut wiedervereint", description = "Dank Euch sind alle blauen Drachen erfasst, {name}. Wir können uns nun wieder daran machen, die Magie von Azeroth zu hüten und sicherzustellen, dass ihre Macht nicht missbraucht wird.\n\nIch glaube, eine Rede ist angebracht. Würdet Ihr mir die Ehre erweisen, dafür anwesend zu sein? \n\nDanach können wir zum Nexus gehen, um zu herauszufinden, was Azuregos über die arkanen Erinnerungen von Sindragosa und Malygos herausgefunden hat.", sourceObjective = "Hört Euch die Rede von Kalecgos an.", progress = "Schön zu sehen, dass so viele blaue Drachen zurückgekehrt sind.", completion = "Es scheint, als wäre das eine kurze Wiedervereinigung gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[75257] = { id = 75257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegshort" }
quests[75258] = { id = 75258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letztes Wort", description = "Ich habe Mayla in Valdrakken eine Nachricht geschickt, um sie wissen zu lassen, was hier geschehen ist. Es wird sie freuen, von mir zu hören... und sie wird froh sein, dass sie Euch zurecht hierher geschickt hat. \n\nBevor Ihr geht möchte ich noch kurz mit Euch sprechen.", sourceObjective = "Sprecht mit Baine.", completion = "{name}, es gibt nur Wenige, die sich so viele Mühe gegeben hätten, mir bei diesem Unterfangen zu helfen. Diese Angelegenheit betraf Euch nicht persönlich, und doch habt Ihr Euer Leben für mich riskiert.\n\nDafür bin ich Euch zutiefst dankbar. Solltet Ihr eines Tages meine Hilfe benötigen, lasst es mich einfach wissen.\n\n\n\nJetzt bleibt nur noch eine Person, mit der ich sprechen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[75259] = { id = 75259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützt das Abkommen: Gewölbe von Zskera", description = "Unsere Verbündeten brauchen einmal mehr Eure Unterstützung bei ihren Vorhaben auf den Inseln. In Valdrakken gehen Worte des Trostes um, die davon sprechen, wie Ihr geholfen habt, unsere Zukunft zu formen.\n\nDoch zurück zur Sache.\n\nAuf der Verbotenen Insel stoßen die Pfadfinder der Drachenschuppenexpedition tiefer in das Gewölbe von Zskera vor. Sie suchen tapfere Abenteurer, die ihnen bei der Erforschung dieser neuen Mysterien helfen.\n\nWir erwarten Eure Rückkehr, {name}.", sourceObjective = "Reist zur Verbotenen Insel, um die Schlüssel des Gewölbes von Zskera zu erhalten, und öffnet damit die Tore des Gewölbes von Zskera. Führt Eure Bemühungen fort, dem Valdrakkenabkommen und seinen Verbündeten auf den ganzen Dracheninseln zu helfen.", completion = "Das sind wundervolle Neuigkeiten! Das Abkommen wird froh sein, von Euren Taten zu hören.\n\nNehmt bitte dies als Zeichen unserer Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[75261] = { id = 75261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mitte der Insel", description = "Ihr und Eure Drachen genießt Eure Abenteuer auf der Verbotenen Insel, nicht wahr? \n\nIch habe gehört, dass der Wind im westlichen Teil der Insel heute besonders gut ist. Wollt Ihr es nicht mit ein paar Rennstrecken dort probieren?", sourceObjective = "Fliegt auf den Rennstrecken des Zentrums der Verbotenen Insel.\n\nBeendet ein beliebiges der beiden fortgeschrittenen oder umgekehrten Rennen, um die Quest sofort abzuschließen.", completion = "Wie es aussieht, habt Ihr beide Euch gut angestrengt. Weiter so!", sourceObjectiveStatus = "unverified-source-field" }
quests[75263] = { id = 75263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Süden der Insel", description = "Ihr und Eure Drachen genießt Eure Abenteuer auf der Verbotenen Insel, nicht wahr? \n\nIch habe gehört, dass der Wind im westlichen Teil der Insel heute besonders gut ist. Wollt Ihr es nicht mit ein paar Rennstrecken dort probieren?", sourceObjective = "Fliegt auf den Rennstrecken der südlichen Verbotenen Insel.\n\nBeendet ein beliebiges der beiden fortgeschrittenen oder umgekehrten Rennen, um die Quest sofort abzuschließen.", completion = "Wie es aussieht, habt Ihr beide Euch gut angestrengt. Weiter so!", sourceObjectiveStatus = "unverified-source-field" }
quests[75265] = { id = 75265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine dringende Angelegenheit", description = "<Der Agent schaut Euch an und nickt.>\n\nIch habe einen dringenden Brief für Euch. In der Burg ist etwas geschehen. \n\nIch empfehle, dass Ihr ihn schnellstmöglich durchlest. \n\nUnd behaltet dies für Euch.", sourceObjective = "Trefft Euch mit Meister Mathias Shaw auf dem äußeren Wall hinter der Burg Sturmwind.\n\nBereitgestellter Gegenstand:", completion = "Gut, dass Ihr da seid.", sourceObjectiveStatus = "unverified-source-field" }
