quests[75280] = { id = 75280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchdringungslager: Gefrierbrand" }
quests[75285] = { id = 75285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alcanon" }
quests[75286] = { id = 75286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaufeln-sterbummel", description = "Die Sippe von Loamm bedarf der Fähigkeiten eines erfahrenen Schmiedes! Wir haben von den Wundern gehört, die Ihr Oberländer aus geschmolzenem Erz herstellt!\n\nUnser Flammenmeister, Herr Crubus, hat gehört, dass Ihr einen Weg gefunden habt, ohne Krallen oder Erdmagie zu graben! Was für eine faszinierende Erfindung!\n\nBringt ihm bitte so bald wie möglich einige dieser \"Schaufeln\", ja?", sourceObjective = "Bringt robuste Expeditionsschaufeln zu Flammenmeister Crubus in Loamm.", progress = "Wer seid Ihr? Oh, Kayann schickt Euch?\n\nNun, habt Ihr, worum ich gebeten habe, oder was?", completion = "Das sind also diese... Wie habt Ihr sie nochmal genannt? Schaufeln?\n\nUnd Ihr haltet sie in den Händen und bewegt Erde damit? Soso.\n\nIch will ehrlich mit Euch sein. Ich bin ein alter Niffen. Ich hoffe einfach, dass sie mir ersparen, mich so viel zu bücken.\n\nNun, dann wollen wir mal!", sourceObjectiveStatus = "unverified-source-field" }
quests[75288] = { id = 75288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberhafte Schriften mit Topuiz", description = "Die Sippe von Loamm bedarf der Fähigkeiten eines herausragenden Verzauberers! In dieser wundervollen Stadt ist Magie so allgegenwärtig, dass sie geradezu mit jedem Windzug durch die Stadt getragen wird!\n\nUnser oberster Staubhändler und Funkelfinger, Herr Topuiz, hat von den vielen verschiedenen Arten gehört, wie Ihr an der Oberfläche Eure Kleider verzaubert, und würde sich gerne ein paar davon persönlich ansehen!\n\nKönnt Ihr ihm bitte so bald wie möglich diese Schriftrollen bringen?", sourceObjective = "Bringt die Schriftrollen Umhang - Schriftstück des Lebensraubs, Umhang - Schriftstück der Geschwindigkeit und Umhang - Schriftstück der Vermeidung zu Staubhändler Topuiz in Loamm.", progress = "Grüße, mein Freund! Ihr riecht neu!\n\nWas führt Euch zum Staubhändler?", completion = "Oh, die Schriftrollen, die ich bei Kayann bestellt habe! Wunderbar!\n\nMmm, die duften nach Magie! Mal sehen, was ich mit denen alles anfangen kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[75289] = { id = 75289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tintenmeister", description = "Die Sippe von Loamm benötigt die Fähigkeiten eines Schreibers! Wir Niffen haben von den mächtigen magischen Schriftstücken gehört, die Ihr an der Oberfläche herstellt, und möchten Eure Arbeit mit unserer eigenen Nase riechen!\n\nUnsere Meistermetzin, Frau Scridorsa, hat darum gebeten, dass je eine Probe Eurer Pigmente und Runensteine hier heruntergebracht wird.\n\nKönnt Ihr die Sachen bitte so bald wie möglich nach Loamm liefern?", sourceObjective = "Bringt schimmernde Pigmente und frostige Runen zu Scridorsa der Metzin in Loamm.", progress = "Hmm? Kann ich Euch helfen?\n\nIch bin sehr beschäftigt, wisst Ihr?", completion = "Was ist das? Warum gebt Ihr mir das?\n\n...\n\nOH! Das sind die Gegenstände, um die ich Kayann gebeten habe! Warum habt Ihr das nicht gleich gesagt?", sourceObjectiveStatus = "unverified-source-field" }
quests[75290] = { id = 75290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesehen bei den Niffen von Loamm", description = "Oh, hallo Ihr!\n\nWir wollen Euch für all Eure Hilfe danken! Trefft mich doch in Loamm, damit wir Euch etwas schönes geben können.\n\nGute Arbeit, immer weiter so!", sourceObjective = "Sprecht mit Mimuup in Loamm.", completion = "Ihr macht das toll! Danke für all Eure Hilfe, wir wissen das zu schätzen!\n\nHoffentlich wird das für Euch nützlich sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[75292] = { id = 75292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Professor Gastrinax" }
quests[75293] = { id = 75293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelswaldtour - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[75294] = { id = 75294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelswaldtour - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[75296] = { id = 75296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Generalin Zskorro" }
quests[75298] = { id = 75298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefenlichtkönigin" }
quests[75301] = { id = 75301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neblies gemischte Magie", description = "Die Sippe von Loamm benötigt die Fähigkeiten eines Alchemisten! Wir haben Geschichten von den wundersamen Gebräuen gehört, die Ihr Oberländer entwickelt habt!\n\nWir haben hier unten auch Alchemisten! Frau Neblie bittet um diese Gegenstände.\n\nBringt die Lieferung bitte so schnell Ihr könnt nach Loamm, ja?", sourceObjective = "Bringt lufterfüllte Manatränke und Omnium Draconis zu Neblie in Loamm.", progress = "Hat Kayann Euch geschickt? Habt Ihr, worum ich gebeten habe?", completion = "Ah, Ihr seid also ein Alchemist? Lasst mich mal sehen!\n\nSehr gut, sehr sehr gut! Haltet etwas Abstand, während ich meine Magie wirke!", sourceObjectiveStatus = "unverified-source-field" }
quests[75304] = { id = 75304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich brauche... einen Schneider", description = "Die Sippe von Loamm benötigt sie Fähigkeiten eines talentierten Schneiders! Wir Niffen sind unendlich neugierig auf die magischen Gewänder, die Ihr herstellt!\n\nWir haben unsere eigenen Näher und Kleidermacher hier unten. Herr Rossmar ist interessiert, hochwertige Stoffballen zu erstehen!\n\nKönnt Ihr die Sachen bitte so bald wie möglich nach Loamm liefern?", sourceObjective = "Bringt schillernde Wildstoffballen zu Rossmar in Loamm.", progress = "Hat Kayann Euch geschickt? Der Erde sei Dank!\n\nIch brauche diese Stoffballen, und zwar schnell!", completion = "Oooh, das ist ein wundervoller Stoff! Er gleitet so sanft durch meine Klauen, fühlt sich aber fest genug an, um täglicher Nutzung standzuhalten!\n\nUnd Ihr habt ihn mir gerade rechtzeitig gebracht! Was so dringend ist? Na ja...", sourceObjectiveStatus = "unverified-source-field" }
quests[75305] = { id = 75305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funken des Lebens: Zaralekhöhle", description = "Die Zaralekhöhle liegt unter den Dracheninseln. Begebt Euch dorthin und erkundet sie. Findet heraus, was Ihr dort ausgraben könnt, aber hütet Euch vor Feinden, denen Ihr dort begegnen werdet.", sourceObjective = "Sammelt 100 Funken des Lebens in der Zaralekhöhle, während Ihr im Kriegsmodus seid.", progress = "Jetzt zieht hinaus.", completion = "Gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[75307] = { id = 75307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nächster Halt: Stadt mit Geschmack", description = "Die Sippe von Loamm benötigt die Fähigkeiten eines Kochs! Wir Niffen sind sehr stolz auf unsere Kochkunst und möchten etwas von der Oberfläche probieren!\n\nEiner unserer besten Köche, Herr Phiary, hat von den intensiven Gewürzen gehört, die in Gerichten der Zentauren der Maruuk verwendet werden, und den komplexen Geschmackskombinationen des Essens der Tuskarr von Iskaara. Nun will er sie selbst kosten!\n\nBringt uns bitte beides nach Loamm sobald Ihr könnt, ja?", sourceObjective = "Bringt Yusas herzhaften Eintopf und Großbankett der Kalu'ak zu Phiary in Loamm.", progress = "He da! Ihr solltet Abstand halten, hier drin geht es gleich heiß her!", completion = "Oh, OH! Dieser Duft! Neu und stinköstlich!\n\nIhr habt bestimmt dieses Futter, um das ich gebeten habe! Probieren wir ihn!", sourceObjectiveStatus = "unverified-source-field" }
quests[75308] = { id = 75308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrybbils Ingenieurskunst", description = "Die Sippe von Loamm benötigt die Fähigkeiten eines Ingenieurs! Wir haben von den wundersamen Maschinen gehört, die in dieser Stadt erfunden werden, und wollen sie unter der Erde einsetzen!\n\nWir haben unseren eigenen Ingenieur da unten, Herr Scrybbil, der ganz besonders interessiert an den Dingen ist, die Ihr \"Angelruten\" nennt. Wie funktioniert sowas? Benutzt Ihr sie, um damit die Fische aufzuspießen? Wie ungewöhnlich!\n\nBringt uns bitte schnellstmöglich diese \"Angelruten\", ja?", sourceObjective = "Bringt Drakoniumanglerfreunde zu Scrybbil in Loamm.", progress = "Tretet näher und bestaunt die fantastischen Erfindungen von Scrybbil! Kann ich Euch etwas Feuerwerk anbieten, werter Herr und/oder werte Dame?\n\nWas sagt Ihr? Ihr habt eine Lieferung für mich?", completion = "Wie wundervoll! Ich habe diesen Tag erwartet!\n\nHier unten nutzen wir nur unsere Klauen zum Fischen. Es ist etwas barbarisch und nicht besonders effizient. Jetzt kann ich das hier benutzen und einen ganzen Berg Fische fangen!\n\n...Wie funktioniert das?", sourceObjectiveStatus = "unverified-source-field" }
quests[75309] = { id = 75309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schöne Steine", description = "Die Sippe von Loamm bedarf der Fähigkeiten eines Juwelenschleifers! Ich habe die wundersamen, glitzernden Edelsteine dieser prächtigen Stadt gesehen, und die Niffen weiter unten würden sie auch gerne sehen. Wir sehen nicht besonders gut, von daher wissen wir ein schönes Glitzern besonders zu schätzen!\n\nUnsere oberste Edelsteinschnüfflerin und Juwelenpoliererin, Frau Fanilly, möchte ein paar schöne Edelsteine sehen. Sie würde die Edelsteine, die nach Alexstrasza und Ysera benannt sind, sicherlich lieben!\n\nKönnt Ihr sie bitte so bald wie möglich nach Loamm liefern?", sourceObjective = "Bringt seidigen Juwelenstaub, Alexstraszite und Ysmaragde zu Fanilly in Loamm.", progress = "Hallo, hallo! Hat Kayann Euch geschickt?\n\nIch kann es kaum erwarten, diese Edelsteine in die Finger zu bekommen!", completion = "Oh, sind das die Edelsteine? Hmmm... Ich muss zugeben, ich hatte sie mir hübscher vorgestellt!\n\nWahrscheinlich müssen sie nur auf Hochglanz poliert werden! Schaut her!", sourceObjectiveStatus = "unverified-source-field" }
quests[75310] = { id = 75310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterwanderung", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
