quests[75350] = { id = 75350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niffengreifer" }
quests[75351] = { id = 75351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagt jedermann, was Leder kann", description = "Die Sippe von Loamm bedarf der Fähigkeiten eines Lederverarbeiters! Wir haben von den Wundern gehört, die Ihr Oberländer aus Bälgen und Schnuppen herstellt!\n\nWir haben hier unten auch Lederverarbeiter! Frau Garram hat von magischen Trommeln gehört, die einen schneller machen sollen! Ist so etwas möglich?\n\nBringt die Lieferung bitte so schnell Ihr könnt nach Loamm, ja?", sourceObjective = "Bringt Wildbalgtrommeln zu Garram in Loamm.", progress = "Hat Kayann Euch geschickt? Habt Ihr, worum ich gebeten habe?", completion = "Aha! Das sind also die beschleunigenden Trommeln? Ich hoffe, dass sie mir dabei helfen, mich schneller zu bewegen und mehr Arbeit zu erledigen.\n\nWir Niffen haben auch Trommeln, aber keine wie diese! Probieren wir sie aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[75353] = { id = 75353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dinn" }
quests[75354] = { id = 75354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myzelienmeister", description = "Hallo, Fremdling! Ich habe eine Idee, zu der ich Eure Meinung möchte.\n\nDie Pilze, die in der Zaralekhöhle wachsen, haben ein dickes, mächtiges Myzel, das sich selbst in die härtesten Kristalle gräbt.\n\nStellt Euch nur vor, was mit einem solchen Material möglich wäre! Ich habe einen Freund in Loamm, der versucht, daraus Leder zu machen!\n\nHabt Ihr Interesse? Bringt meinem Freund Garram ein paar Pilze!", sourceObjective = "Sammelt 10 Nachtlichtrossglockenproben und bringt sie zu Garram in Loamm.", progress = "Wir nennen diese Pilze an den Kristallen Nachtlichtrossglocken. Sie strahlen nicht nur Licht aus, sie haben auch einen starken Geruch und helfen dabei, uns mit unseren Nasen zurechtzufinden!", completion = "Was?! An denen sind ja kaum Myzelien dran!\n\n<Garram denkt nach.>\n\nIch frage mich... ob die Myzelien wohl im Kristall zurückbleiben? \n\nHmm... Ich werde versuchen, hier noch mehr davon zu züchten und damit zu experimentieren. Danke für die Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
